"""Karnataka PUC physics practicals that needed their own benches: measuring
instruments, the galvanometer, the sonometer laws, a liquid's refractive index
and the flywheel. Written for KINETIX; every lab is reviewed=False until a
subject teacher checks it."""


def add(lab, W, Q):
    puc1 = dict(subject='Physics', domain='physics', levels=[11], curricula=['ka-puc', 'cbse', 'ncert'])
    puc2 = dict(subject='Physics', domain='physics', levels=[12], curricula=['ka-puc', 'cbse', 'ncert'])
    ZERO = W('Find the zero error first and subtract it from every reading.', 'पहले शून्य त्रुटि ज्ञात करें और उसे हर पाठ्यांक से घटाएँ।', 'ಮೊದಲು ಶೂನ್ಯ ದೋಷ ಕಂಡುಹಿಡಿದು ಪ್ರತಿ ಓದಿನಿಂದ ಕಳೆಯಿರಿ.')
    MEAN = W('Take each reading at least three times and use the mean.', 'हर पाठ्यांक कम से कम तीन बार लें और माध्य लें।', 'ಪ್ರತಿ ಓದನ್ನು ಕನಿಷ್ಠ ಮೂರು ಬಾರಿ ತೆಗೆದು ಸರಾಸರಿ ಬಳಸಿ.')
    PARALLAX = W('Keep your eye directly in front of the scale to avoid parallax.', 'लंबन से बचने के लिए आँख पैमाने के ठीक सामने रखें।', 'ದೃಷ್ಟಿಭ್ರಮೆ ತಪ್ಪಿಸಲು ಕಣ್ಣನ್ನು ಅಳತೆಪಟ್ಟಿಯ ನೇರ ಮುಂದೆ ಇಡಿ.')
    KEYS = W('Put the key in only while taking a reading.', 'केवल पाठ्यांक लेते समय ही कुंजी लगाएँ।', 'ಓದು ತೆಗೆಯುವಾಗ ಮಾತ್ರ ಕೀಲಿ ಹಾಕಿ.')
    WIRES = W('Clean the wire ends and tighten every connection.', 'तारों के सिरे साफ़ करें और हर संयोजन कसें।', 'ತಂತಿಯ ತುದಿಗಳನ್ನು ಸ್ವಚ್ಛಗೊಳಿಸಿ ಪ್ರತಿ ಸಂಪರ್ಕ ಬಿಗಿಗೊಳಿಸಿ.')
    BATTERY = W('Battery or accumulator', 'बैटरी या संचायक', 'ಬ್ಯಾಟರಿ ಅಥವಾ ಸಂಚಯಕ')
    PLUGKEY = W('Plug keys and connecting wires', 'प्लग कुंजियाँ और संयोजक तार', 'ಪ್ಲಗ್ ಕೀಲಿಗಳು ಮತ್ತು ಸಂಪರ್ಕ ತಂತಿಗಳು')
    GALV = W('Weston galvanometer (30-0-30)', 'वेस्टन धारामापी (30-0-30)', 'ವೆಸ್ಟನ್ ಗ್ಯಾಲ್ವನೋಮೀಟರ್ (30-0-30)')
    RBOX = W('Resistance boxes', 'प्रतिरोध बॉक्स', 'ರೋಧ ಪೆಟ್ಟಿಗೆಗಳು')

    # ------------------------------------------------------------ vernier
    lab(id='vernier-callipers', bench='vernier', setup={'task': 'all'}, **puc1,
        keywords=['vernier callipers', 'vernier', 'least count', 'units and measurement', 'measurement', 'zero error', 'volume of a beaker', 'diameter of a sphere'],
        title=W('Vernier callipers: diameter, length and volume', 'वर्नियर कैलिपर्स: व्यास, लंबाई और आयतन', 'ವರ್ನಿಯರ್ ಕ್ಯಾಲಿಪರ್ಸ್: ವ್ಯಾಸ, ಉದ್ದ ಮತ್ತು ಘನಫಲ'),
        summary=W('Close the jaws on a sphere, a cylinder and a beaker, read the main and vernier scales, and work out volumes.', 'जबड़ों को गोले, बेलन और बीकर पर बंद करें, मुख्य और वर्नियर पैमाने पढ़ें और आयतन निकालें।', 'ದವಡೆಗಳನ್ನು ಗೋಳ, ಸಿಲಿಂಡರ್ ಮತ್ತು ಬೀಕರ್ ಮೇಲೆ ಮುಚ್ಚಿ, ಮುಖ್ಯ ಮತ್ತು ವರ್ನಿಯರ್ ಅಳತೆಗಳನ್ನು ಓದಿ, ಘನಫಲ ಲೆಕ್ಕಿಸಿ.'),
        aim=W('To measure the diameter of a sphere, the dimensions of a cylinder, and the internal diameter and depth of a beaker with vernier callipers, and hence find their volumes.', 'वर्नियर कैलिपर्स से गोले का व्यास, बेलन की विमाएँ, और बीकर का आंतरिक व्यास और गहराई मापकर उनके आयतन ज्ञात करना।', 'ವರ್ನಿಯರ್ ಕ್ಯಾಲಿಪರ್ಸ್‌ನಿಂದ ಗೋಳದ ವ್ಯಾಸ, ಸಿಲಿಂಡರ್‌ನ ಆಯಾಮಗಳು ಮತ್ತು ಬೀಕರ್‌ನ ಒಳ ವ್ಯಾಸ ಹಾಗೂ ಆಳ ಅಳೆದು ಅವುಗಳ ಘನಫಲ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('10 vernier divisions equal 9 main-scale divisions of 1 mm, so the least count is 1 MSD − 1 VSD = 0.1 mm = 0.01 cm. Reading = MSR + VSC × LC, corrected by subtracting the zero error.', '10 वर्नियर भाग 1 mm के 9 मुख्य पैमाना भागों के बराबर हैं, इसलिए अल्पतमांक 1 MSD − 1 VSD = 0.1 mm = 0.01 cm है। पाठ्यांक = MSR + VSC × LC, जिसमें से शून्य त्रुटि घटाई जाती है।', '10 ವರ್ನಿಯರ್ ವಿಭಾಗಗಳು 1 mm ನ 9 ಮುಖ್ಯ ಅಳತೆ ವಿಭಾಗಗಳಿಗೆ ಸಮ; ಆದ್ದರಿಂದ ಕನಿಷ್ಠ ಎಣಿಕೆ 1 MSD − 1 VSD = 0.1 mm = 0.01 cm. ಓದು = MSR + VSC × LC, ಶೂನ್ಯ ದೋಷ ಕಳೆದು ಸರಿಪಡಿಸಲಾಗುತ್ತದೆ.'),
        apparatus=[W('Vernier callipers', 'वर्नियर कैलिपर्स', 'ವರ್ನಿಯರ್ ಕ್ಯಾಲಿಪರ್ಸ್'), W('Metal sphere (bob) and cylinder', 'धातु का गोला (गोलक) और बेलन', 'ಲೋಹದ ಗೋಳ (ಗುಂಡು) ಮತ್ತು ಸಿಲಿಂಡರ್'), W('Beaker', 'बीकर', 'ಬೀಕರ್')],
        steps=[W('Close the jaws fully and note the zero error with its sign.', 'जबड़े पूरी तरह बंद करके शून्य त्रुटि उसके चिह्न सहित लिखें।', 'ದವಡೆಗಳನ್ನು ಸಂಪೂರ್ಣ ಮುಚ್ಚಿ ಶೂನ್ಯ ದೋಷವನ್ನು ಅದರ ಚಿಹ್ನೆಯೊಂದಿಗೆ ಬರೆಯಿರಿ.'),
               W('Hold the sphere between the lower jaws, close them gently and read MSR and the coinciding vernier division.', 'गोले को निचले जबड़ों के बीच रखें, धीरे से बंद करें और MSR तथा संपाती वर्नियर भाग पढ़ें।', 'ಗೋಳವನ್ನು ಕೆಳಗಿನ ದವಡೆಗಳ ನಡುವೆ ಹಿಡಿದು ನಿಧಾನವಾಗಿ ಮುಚ್ಚಿ, MSR ಮತ್ತು ಹೊಂದಿಕೆಯಾಗುವ ವರ್ನಿಯರ್ ವಿಭಾಗ ಓದಿ.'),
               W('Turn the object and repeat; measure the cylinder’s diameter and length the same way.', 'वस्तु घुमाकर दोहराएँ; बेलन का व्यास और लंबाई इसी तरह मापें।', 'ವಸ್ತುವನ್ನು ತಿರುಗಿಸಿ ಪುನರಾವರ್ತಿಸಿ; ಸಿಲಿಂಡರ್‌ನ ವ್ಯಾಸ ಮತ್ತು ಉದ್ದವನ್ನು ಹಾಗೆಯೇ ಅಳೆಯಿರಿ.'),
               W('Use the upper jaws for the beaker’s internal diameter and the depth rod for its depth.', 'बीकर के आंतरिक व्यास के लिए ऊपरी जबड़े और गहराई के लिए गहराई छड़ का उपयोग करें।', 'ಬೀಕರ್‌ನ ಒಳ ವ್ಯಾಸಕ್ಕೆ ಮೇಲಿನ ದವಡೆಗಳು ಮತ್ತು ಆಳಕ್ಕೆ ಆಳದ ಕಡ್ಡಿಯನ್ನು ಬಳಸಿ.'),
               W('Correct the means for zero error and work out V = πd³/6, πd²l/4 and πd²h/4.', 'माध्यों में शून्य त्रुटि का संशोधन करें और V = πd³/6, πd²l/4 और πd²h/4 निकालें।', 'ಸರಾಸರಿಗಳನ್ನು ಶೂನ್ಯ ದೋಷಕ್ಕೆ ಸರಿಪಡಿಸಿ V = πd³/6, πd²l/4 ಮತ್ತು πd²h/4 ಲೆಕ್ಕಿಸಿ.')],
        precautions=[ZERO, W('Close the jaws gently; do not press the object.', 'जबड़े धीरे से बंद करें; वस्तु को दबाएँ नहीं।', 'ದವಡೆಗಳನ್ನು ನಿಧಾನವಾಗಿ ಮುಚ್ಚಿ; ವಸ್ತುವನ್ನು ಒತ್ತಬೇಡಿ.'), PARALLAX],
        conclusion=W('The vernier reads to 0.01 cm; with the zero error removed, the mean dimensions give the volumes of the sphere, the cylinder and the beaker.', 'वर्नियर 0.01 cm तक पढ़ता है; शून्य त्रुटि हटाने पर माध्य विमाएँ गोले, बेलन और बीकर के आयतन देती हैं।', 'ವರ್ನಿಯರ್ 0.01 cm ವರೆಗೆ ಓದುತ್ತದೆ; ಶೂನ್ಯ ದೋಷ ತೆಗೆದ ಸರಾಸರಿ ಆಯಾಮಗಳು ಗೋಳ, ಸಿಲಿಂಡರ್ ಮತ್ತು ಬೀಕರ್‌ನ ಘನಫಲ ನೀಡುತ್ತವೆ.'),
        viva=[Q(W('What is the least count of these callipers?', 'इन कैलिपर्स का अल्पतमांक क्या है?', 'ಈ ಕ್ಯಾಲಿಪರ್ಸ್‌ನ ಕನಿಷ್ಠ ಎಣಿಕೆ ಎಷ್ಟು?'), W('0.01 cm: 1 MSD (1 mm) minus 1 VSD (0.9 mm).', '0.01 cm: 1 MSD (1 mm) में से 1 VSD (0.9 mm) घटाकर।', '0.01 cm: 1 MSD (1 mm) ನಿಂದ 1 VSD (0.9 mm) ಕಳೆದು.')),
              Q(W('When is the zero error positive?', 'शून्य त्रुटि धनात्मक कब होती है?', 'ಶೂನ್ಯ ದೋಷ ಧನಾತ್ಮಕವಾಗುವುದು ಯಾವಾಗ?'), W('When the vernier zero lies to the right of the main-scale zero with the jaws closed.', 'जब जबड़े बंद होने पर वर्नियर का शून्य मुख्य पैमाने के शून्य के दाईं ओर हो।', 'ದವಡೆಗಳು ಮುಚ್ಚಿದಾಗ ವರ್ನಿಯರ್ ಶೂನ್ಯ ಮುಖ್ಯ ಅಳತೆಯ ಶೂನ್ಯದ ಬಲಕ್ಕಿದ್ದಾಗ.')),
              Q(W('What are the upper jaws for?', 'ऊपरी जबड़े किसलिए हैं?', 'ಮೇಲಿನ ದವಡೆಗಳು ಯಾವುದಕ್ಕೆ?'), W('For internal measurements, such as the inside diameter of a beaker.', 'आंतरिक मापों के लिए, जैसे बीकर का भीतरी व्यास।', 'ಒಳ ಅಳತೆಗಳಿಗೆ, ಉದಾ. ಬೀಕರ್‌ನ ಒಳ ವ್ಯಾಸ.')),
              Q(W('Why is the vernier more precise than a metre scale?', 'वर्नियर मीटर पैमाने से अधिक परिशुद्ध क्यों है?', 'ವರ್ನಿಯರ್ ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿಗಿಂತ ಏಕೆ ಹೆಚ್ಚು ನಿಖರ?'), W('It divides a millimetre into ten by comparing two slightly different scales.', 'यह दो थोड़े भिन्न पैमानों की तुलना से एक मिलीमीटर को दस भागों में बाँटता है।', 'ಸ್ವಲ್ಪ ಭಿನ್ನವಾದ ಎರಡು ಅಳತೆಗಳನ್ನು ಹೋಲಿಸಿ ಒಂದು ಮಿಲಿಮೀಟರನ್ನು ಹತ್ತು ಭಾಗ ಮಾಡುತ್ತದೆ.')),
              Q(W('Which error is reduced by taking several readings?', 'कई पाठ्यांक लेने से कौन सी त्रुटि घटती है?', 'ಹಲವು ಓದುಗಳನ್ನು ತೆಗೆಯುವುದರಿಂದ ಯಾವ ದೋಷ ಕಡಿಮೆಯಾಗುತ್ತದೆ?'), W('Random error; the zero error is a systematic error and must be subtracted.', 'यादृच्छिक त्रुटि; शून्य त्रुटि क्रमबद्ध त्रुटि है जिसे घटाना पड़ता है।', 'ಯಾದೃಚ್ಛಿಕ ದೋಷ; ಶೂನ್ಯ ದೋಷ ವ್ಯವಸ್ಥಿತ ದೋಷ, ಅದನ್ನು ಕಳೆಯಬೇಕು.'))])

    # -------------------------------------------------------- screw gauge
    lab(id='screw-gauge', bench='screw-gauge', setup={'task': 'all'}, **puc1,
        keywords=['screw gauge', 'micrometer', 'least count', 'pitch', 'units and measurement', 'diameter of a wire', 'thickness of a sheet', 'zero error'],
        title=W('Screw gauge: diameter of a wire and thickness of a sheet', 'स्क्रू गेज: तार का व्यास और चादर की मोटाई', 'ಸ್ಕ್ರೂ ಗೇಜ್: ತಂತಿಯ ವ್ಯಾಸ ಮತ್ತು ಹಾಳೆಯ ದಪ್ಪ'),
        summary=W('Turn the ratchet until it clicks on a wire or a sheet, read the sleeve and the thimble, and correct for zero error.', 'तार या चादर पर रैचेट के क्लिक करने तक घुमाएँ, स्लीव और थिम्बल पढ़ें, और शून्य त्रुटि सुधारें।', 'ತಂತಿ ಅಥವಾ ಹಾಳೆಯ ಮೇಲೆ ರ್ಯಾಚೆಟ್ ಕ್ಲಿಕ್ ಆಗುವವರೆಗೆ ತಿರುಗಿಸಿ, ಸ್ಲೀವ್ ಮತ್ತು ಥಿಂಬಲ್ ಓದಿ, ಶೂನ್ಯ ದೋಷ ಸರಿಪಡಿಸಿ.'),
        aim=W('To measure the diameter of a given wire and the thickness of a given sheet using a screw gauge.', 'स्क्रू गेज से दिए गए तार का व्यास और दी गई चादर की मोटाई मापना।', 'ಸ್ಕ್ರೂ ಗೇಜ್ ಬಳಸಿ ನೀಡಿದ ತಂತಿಯ ವ್ಯಾಸ ಮತ್ತು ಹಾಳೆಯ ದಪ್ಪ ಅಳೆಯುವುದು.'),
        principle=W('One turn of the thimble moves the spindle by the pitch (1 mm); the head has 100 divisions, so the least count is 1 mm ÷ 100 = 0.01 mm. Reading = PSR + HSC × LC − zero error.', 'थिम्बल का एक चक्कर स्पिंडल को पिच (1 mm) जितना खिसकाता है; शीर्ष पर 100 भाग हैं, इसलिए अल्पतमांक 1 mm ÷ 100 = 0.01 mm है। पाठ्यांक = PSR + HSC × LC − शून्य त्रुटि।', 'ಥಿಂಬಲ್‌ನ ಒಂದು ಸುತ್ತು ಸ್ಪಿಂಡಲನ್ನು ಪಿಚ್ (1 mm) ನಷ್ಟು ಸರಿಸುತ್ತದೆ; ತಲೆಯಲ್ಲಿ 100 ವಿಭಾಗಗಳಿವೆ, ಆದ್ದರಿಂದ ಕನಿಷ್ಠ ಎಣಿಕೆ 1 mm ÷ 100 = 0.01 mm. ಓದು = PSR + HSC × LC − ಶೂನ್ಯ ದೋಷ.'),
        apparatus=[W('Screw gauge', 'स्क्रू गेज', 'ಸ್ಕ್ರೂ ಗೇಜ್'), W('Wire', 'तार', 'ತಂತಿ'), W('Metal or glass sheet', 'धातु या काँच की चादर', 'ಲೋಹ ಅಥವಾ ಗಾಜಿನ ಹಾಳೆ')],
        steps=[W('Find the pitch and the least count from the scales.', 'पैमानों से पिच और अल्पतमांक ज्ञात करें।', 'ಅಳತೆಗಳಿಂದ ಪಿಚ್ ಮತ್ತು ಕನಿಷ್ಠ ಎಣಿಕೆ ಕಂಡುಹಿಡಿಯಿರಿ.'),
               W('Bring the faces together with the ratchet and note the zero error.', 'रैचेट से फलकों को मिलाएँ और शून्य त्रुटि लिखें।', 'ರ್ಯಾಚೆಟ್‌ನಿಂದ ಮುಖಗಳನ್ನು ಸೇರಿಸಿ ಶೂನ್ಯ ದೋಷ ಬರೆಯಿರಿ.'),
               W('Place the wire between the anvil and the spindle and turn the ratchet until it clicks.', 'तार को एन्विल और स्पिंडल के बीच रखें और रैचेट को क्लिक होने तक घुमाएँ।', 'ತಂತಿಯನ್ನು ಅನ್ವಿಲ್ ಮತ್ತು ಸ್ಪಿಂಡಲ್ ನಡುವೆ ಇಟ್ಟು ರ್ಯಾಚೆಟ್ ಕ್ಲಿಕ್ ಆಗುವವರೆಗೆ ತಿರುಗಿಸಿ.'),
               W('Read PSR on the sleeve and the head-scale division on the reference line.', 'स्लीव पर PSR और संदर्भ रेखा पर शीर्ष पैमाने का भाग पढ़ें।', 'ಸ್ಲೀವ್‌ನಲ್ಲಿ PSR ಮತ್ತು ಉಲ್ಲೇಖ ರೇಖೆಯ ಮೇಲಿನ ತಲೆ ಅಳತೆಯ ವಿಭಾಗ ಓದಿ.'),
               W('Repeat at different places and in perpendicular directions; then measure the sheet.', 'अलग-अलग स्थानों और लंबवत दिशाओं में दोहराएँ; फिर चादर मापें।', 'ಬೇರೆ ಬೇರೆ ಸ್ಥಳಗಳಲ್ಲಿ ಮತ್ತು ಲಂಬ ದಿಕ್ಕುಗಳಲ್ಲಿ ಪುನರಾವರ್ತಿಸಿ; ನಂತರ ಹಾಳೆ ಅಳೆಯಿರಿ.')],
        precautions=[W('Always turn by the ratchet, never by the thimble, so the pressure is the same.', 'हमेशा रैचेट से घुमाएँ, थिम्बल से कभी नहीं, ताकि दबाव समान रहे।', 'ಒತ್ತಡ ಒಂದೇ ಇರಲು ಯಾವಾಗಲೂ ರ್ಯಾಚೆಟ್‌ನಿಂದ ತಿರುಗಿಸಿ, ಥಿಂಬಲ್‌ನಿಂದ ಎಂದೂ ಅಲ್ಲ.'), W('Turn in one direction only, to avoid backlash.', 'पश्च-गति से बचने के लिए केवल एक दिशा में घुमाएँ।', 'ಹಿಂಚಲನೆ ತಪ್ಪಿಸಲು ಒಂದೇ ದಿಕ್ಕಿನಲ್ಲಿ ತಿರುಗಿಸಿ.'), ZERO],
        conclusion=W('The screw gauge reads to 0.01 mm; the corrected mean gives the wire’s diameter (and its cross-section πd²/4) and the sheet’s thickness.', 'स्क्रू गेज 0.01 mm तक पढ़ता है; संशोधित माध्य तार का व्यास (और उसका अनुप्रस्थ क्षेत्र πd²/4) तथा चादर की मोटाई देता है।', 'ಸ್ಕ್ರೂ ಗೇಜ್ 0.01 mm ವರೆಗೆ ಓದುತ್ತದೆ; ಸರಿಪಡಿಸಿದ ಸರಾಸರಿ ತಂತಿಯ ವ್ಯಾಸ (ಮತ್ತು ಅಡ್ಡಛೇದ πd²/4) ಹಾಗೂ ಹಾಳೆಯ ದಪ್ಪ ನೀಡುತ್ತದೆ.'),
        viva=[Q(W('What is the pitch of a screw?', 'स्क्रू की पिच क्या है?', 'ಸ್ಕ್ರೂವಿನ ಪಿಚ್ ಎಂದರೇನು?'), W('The distance it advances in one full turn.', 'एक पूरे चक्कर में वह जितना आगे बढ़ता है।', 'ಒಂದು ಪೂರ್ಣ ಸುತ್ತಿನಲ್ಲಿ ಅದು ಮುಂದುವರಿಯುವ ದೂರ.')),
              Q(W('What is backlash error?', 'पश्च-गति त्रुटि क्या है?', 'ಹಿಂಚಲನೆ ದೋಷ ಎಂದರೇನು?'), W('Lost motion when the turning direction is reversed, because of wear in the threads.', 'घुमाने की दिशा उलटने पर चूड़ियों के घिसाव के कारण होने वाली व्यर्थ गति।', 'ತಿರುಗಿಸುವ ದಿಕ್ಕು ಬದಲಿಸಿದಾಗ ಚಡಿಗಳ ಸವೆತದಿಂದ ಆಗುವ ವ್ಯರ್ಥ ಚಲನೆ.')),
              Q(W('Why is a ratchet provided?', 'रैचेट क्यों दिया जाता है?', 'ರ್ಯಾಚೆಟ್ ಏಕೆ ಇದೆ?'), W('It slips at a fixed pressure, so the object is never over-tightened.', 'यह निश्चित दबाव पर फिसल जाता है, जिससे वस्तु ज़्यादा नहीं कसती।', 'ನಿಗದಿತ ಒತ್ತಡದಲ್ಲಿ ಅದು ಜಾರುತ್ತದೆ, ಆದ್ದರಿಂದ ವಸ್ತು ಅತಿಯಾಗಿ ಬಿಗಿಯಾಗುವುದಿಲ್ಲ.')),
              Q(W('When is the zero error negative?', 'शून्य त्रुटि ऋणात्मक कब होती है?', 'ಶೂನ್ಯ ದೋಷ ಋಣಾತ್ಮಕವಾಗುವುದು ಯಾವಾಗ?'), W('When the head-scale zero stays above the reference line with the faces touching.', 'जब फलक छूने पर शीर्ष पैमाने का शून्य संदर्भ रेखा से ऊपर रहे।', 'ಮುಖಗಳು ಸ್ಪರ್ಶಿಸಿದಾಗ ತಲೆ ಅಳತೆಯ ಶೂನ್ಯ ಉಲ್ಲೇಖ ರೇಖೆಯ ಮೇಲಿದ್ದರೆ.')),
              Q(W('Why measure the wire in two perpendicular directions?', 'तार को दो लंबवत दिशाओं में क्यों मापते हैं?', 'ತಂತಿಯನ್ನು ಎರಡು ಲಂಬ ದಿಕ್ಕುಗಳಲ್ಲಿ ಏಕೆ ಅಳೆಯುತ್ತೇವೆ?'), W('The wire may not be perfectly round; the mean allows for that.', 'तार पूरी तरह गोल न हो सकता है; माध्य इसकी पूर्ति करता है।', 'ತಂತಿ ಸಂಪೂರ್ಣ ವೃತ್ತಾಕಾರವಿಲ್ಲದಿರಬಹುದು; ಸರಾಸರಿ ಅದನ್ನು ಸರಿದೂಗಿಸುತ್ತದೆ.'))])

    # -------------------------------------------------------- spherometer
    lab(id='spherometer', bench='spherometer', **puc1,
        keywords=['spherometer', 'radius of curvature', 'units and measurement', 'least count', 'convex surface', 'concave surface', 'pitch'],
        title=W('Radius of curvature with a spherometer', 'गोलाईमापी से वक्रता त्रिज्या', 'ಗೋಳಮಾಪಕದಿಂದ ವಕ್ರತಾ ತ್ರಿಜ್ಯ'),
        summary=W('Read the spherometer on a plane glass plate and on a curved surface; the difference gives h and R = l²/6h + h/2.', 'गोलाईमापी को समतल काँच और वक्र सतह पर पढ़ें; अंतर से h और R = l²/6h + h/2 मिलता है।', 'ಗೋಳಮಾಪಕವನ್ನು ಸಮತಟ್ಟಾದ ಗಾಜು ಮತ್ತು ವಕ್ರ ಮೇಲ್ಮೈ ಮೇಲೆ ಓದಿ; ವ್ಯತ್ಯಾಸ h ಮತ್ತು R = l²/6h + h/2 ನೀಡುತ್ತದೆ.'),
        aim=W('To find the radius of curvature of a given spherical surface using a spherometer.', 'गोलाईमापी से दी गई गोलीय सतह की वक्रता त्रिज्या ज्ञात करना।', 'ಗೋಳಮಾಪಕ ಬಳಸಿ ನೀಡಿದ ಗೋಳೀಯ ಮೇಲ್ಮೈಯ ವಕ್ರತಾ ತ್ರಿಜ್ಯ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('With the legs a distance l apart, the centre of a surface of radius R rises (or sinks) by h relative to the legs: R = l²/6h + h/2. h is the difference of the readings on the surface and on a plane plate.', 'पैरों के बीच दूरी l होने पर R त्रिज्या की सतह का केंद्र पैरों के सापेक्ष h ऊपर (या नीचे) होता है: R = l²/6h + h/2. h सतह और समतल प्लेट पर पाठ्यांकों का अंतर है।', 'ಕಾಲುಗಳ ನಡುವೆ l ದೂರವಿದ್ದಾಗ R ತ್ರಿಜ್ಯದ ಮೇಲ್ಮೈಯ ಕೇಂದ್ರ ಕಾಲುಗಳಿಗೆ ಹೋಲಿಸಿ h ಏರುತ್ತದೆ (ಅಥವಾ ಇಳಿಯುತ್ತದೆ): R = l²/6h + h/2. h ಮೇಲ್ಮೈ ಮತ್ತು ಸಮತಟ್ಟಾದ ಫಲಕದ ಓದುಗಳ ವ್ಯತ್ಯಾಸ.'),
        apparatus=[W('Spherometer', 'गोलाईमापी', 'ಗೋಳಮಾಪಕ'), W('Plane glass plate', 'समतल काँच की प्लेट', 'ಸಮತಟ್ಟಾದ ಗಾಜಿನ ಫಲಕ'), W('Convex lens or watch glass', 'उत्तल लेंस या वॉच ग्लास', 'ಪೀನ ಮಸೂರ ಅಥವಾ ವಾಚ್ ಗ್ಲಾಸ್')],
        steps=[W('Find the pitch and least count; press the legs on paper and measure l.', 'पिच और अल्पतमांक ज्ञात करें; पैरों को कागज़ पर दबाकर l मापें।', 'ಪಿಚ್ ಮತ್ತು ಕನಿಷ್ಠ ಎಣಿಕೆ ಕಂಡುಹಿಡಿಯಿರಿ; ಕಾಲುಗಳನ್ನು ಕಾಗದದ ಮೇಲೆ ಒತ್ತಿ l ಅಳೆಯಿರಿ.'),
               W('Place it on the plane plate and turn the screw until the tip just touches; read.', 'इसे समतल प्लेट पर रखें और स्क्रू को नोक के ठीक छूने तक घुमाएँ; पढ़ें।', 'ಅದನ್ನು ಸಮತಟ್ಟಾದ ಫಲಕದ ಮೇಲಿಟ್ಟು ತುದಿ ಸ್ಪರ್ಶಿಸುವವರೆಗೆ ಸ್ಕ್ರೂ ತಿರುಗಿಸಿ; ಓದಿ.'),
               W('Raise the screw, place it on the curved surface and repeat.', 'स्क्रू ऊपर करें, इसे वक्र सतह पर रखें और दोहराएँ।', 'ಸ್ಕ್ರೂ ಮೇಲೆತ್ತಿ, ವಕ್ರ ಮೇಲ್ಮೈ ಮೇಲಿಟ್ಟು ಪುನರಾವರ್ತಿಸಿ.'),
               W('Take three readings on each and find h from the means.', 'प्रत्येक पर तीन पाठ्यांक लें और माध्यों से h ज्ञात करें।', 'ಪ್ರತಿಯೊಂದರ ಮೇಲೆ ಮೂರು ಓದು ತೆಗೆದು ಸರಾಸರಿಗಳಿಂದ h ಕಂಡುಹಿಡಿಯಿರಿ.'),
               W('Work out R = l²/6h + h/2.', 'R = l²/6h + h/2 निकालें।', 'R = l²/6h + h/2 ಲೆಕ್ಕಿಸಿ.')],
        precautions=[W('Stop as soon as the tip touches: the instrument just begins to rock.', 'नोक छूते ही रुकें: उपकरण बस डगमगाने लगता है।', 'ತುದಿ ಸ್ಪರ್ಶಿಸಿದ ತಕ್ಷಣ ನಿಲ್ಲಿಸಿ: ಉಪಕರಣ ಅಲುಗಾಡಲು ಆರಂಭಿಸುತ್ತದೆ.'), W('Turn in one direction only, to avoid backlash.', 'पश्च-गति से बचने के लिए केवल एक दिशा में घुमाएँ।', 'ಹಿಂಚಲನೆ ತಪ್ಪಿಸಲು ಒಂದೇ ದಿಕ್ಕಿನಲ್ಲಿ ತಿರುಗಿಸಿ.'), MEAN],
        conclusion=W('The difference of readings gives the sag h, and R = l²/6h + h/2 gives the radius of curvature of the surface.', 'पाठ्यांकों का अंतर झुकाव h देता है, और R = l²/6h + h/2 सतह की वक्रता त्रिज्या देता है।', 'ಓದುಗಳ ವ್ಯತ್ಯಾಸ ಕುಸಿತ h ನೀಡುತ್ತದೆ; R = l²/6h + h/2 ಮೇಲ್ಮೈಯ ವಕ್ರತಾ ತ್ರಿಜ್ಯ ನೀಡುತ್ತದೆ.'),
        viva=[Q(W('Why does a spherometer have three legs?', 'गोलाईमापी के तीन पैर क्यों होते हैं?', 'ಗೋಳಮಾಪಕಕ್ಕೆ ಮೂರು ಕಾಲುಗಳು ಏಕೆ?'), W('Three points always define a plane, so it stands steady on any surface.', 'तीन बिंदु सदा एक तल निर्धारित करते हैं, इसलिए यह किसी भी सतह पर स्थिर रहता है।', 'ಮೂರು ಬಿಂದುಗಳು ಯಾವಾಗಲೂ ಒಂದು ಸಮತಲವನ್ನು ನಿರ್ಧರಿಸುತ್ತವೆ; ಹಾಗಾಗಿ ಯಾವ ಮೇಲ್ಮೈಯಲ್ಲೂ ಸ್ಥಿರ.')),
              Q(W('What is l in the formula?', 'सूत्र में l क्या है?', 'ಸೂತ್ರದಲ್ಲಿ l ಎಂದರೇನು?'), W('The mean distance between the legs (a side of the equilateral triangle they form).', 'पैरों के बीच की माध्य दूरी (उनसे बने समबाहु त्रिभुज की भुजा)।', 'ಕಾಲುಗಳ ನಡುವಿನ ಸರಾಸರಿ ದೂರ (ಅವು ರಚಿಸುವ ಸಮಬಾಹು ತ್ರಿಭುಜದ ಬಾಹು).')),
              Q(W('How can you tell the tip has just touched?', 'कैसे पता चले कि नोक ने अभी छुआ है?', 'ತುದಿ ಈಗಷ್ಟೇ ಸ್ಪರ್ಶಿಸಿದೆ ಎಂದು ಹೇಗೆ ತಿಳಿಯುವುದು?'), W('The spherometer starts to rock; its reflection in the glass touches the tip.', 'गोलाईमापी डगमगाने लगता है; काँच में उसका प्रतिबिंब नोक को छूता है।', 'ಗೋಳಮಾಪಕ ಅಲುಗಾಡತೊಡಗುತ್ತದೆ; ಗಾಜಿನಲ್ಲಿ ಅದರ ಪ್ರತಿಬಿಂಬ ತುದಿಯನ್ನು ಸ್ಪರ್ಶಿಸುತ್ತದೆ.')),
              Q(W('For a concave surface, is the reading more or less than on the plane?', 'अवतल सतह पर पाठ्यांक समतल से अधिक है या कम?', 'ನಿಮ್ನ ಮೇಲ್ಮೈಯಲ್ಲಿ ಓದು ಸಮತಟ್ಟಿಗಿಂತ ಹೆಚ್ಚೋ ಕಡಿಮೆಯೋ?'), W('Less: the centre is below the plane of the legs.', 'कम: केंद्र पैरों के तल से नीचे है।', 'ಕಡಿಮೆ: ಕೇಂದ್ರ ಕಾಲುಗಳ ಸಮತಲದ ಕೆಳಗಿದೆ.')),
              Q(W('Where else is the radius of curvature needed?', 'वक्रता त्रिज्या और कहाँ चाहिए?', 'ವಕ್ರತಾ ತ್ರಿಜ್ಯ ಬೇರೆಲ್ಲಿ ಬೇಕು?'), W("In the lens maker's formula and in finding a liquid's refractive index with a lens.", 'लेंस निर्माता सूत्र में और लेंस से द्रव का अपवर्तनांक ज्ञात करने में।', 'ಮಸೂರ ತಯಾರಕರ ಸೂತ್ರದಲ್ಲಿ ಮತ್ತು ಮಸೂರದಿಂದ ದ್ರವದ ವಕ್ರೀಭವನಾಂಕ ಕಂಡುಹಿಡಿಯುವಲ್ಲಿ.'))])

    # ----------------------------------------------------------- flywheel
    lab(id='flywheel-inertia', bench='flywheel', **puc1,
        keywords=['flywheel', 'moment of inertia', 'rotational motion', 'system of particles and rotational motion', 'angular velocity', 'kinetic energy of rotation'],
        title=W('Moment of inertia of a flywheel', 'गतिपालक चक्र का जड़त्व आघूर्ण', 'ಫ್ಲೈವೀಲ್‌ನ ಜಡತ್ವ ಭ್ರಾಮಕ'),
        summary=W('Let a mass unwind a cord from the axle, count the turns the wheel makes after the cord slips off, time them, and find I.', 'एक द्रव्यमान को धुरी से डोरी खोलने दें, डोरी छूटने के बाद चक्र के चक्कर गिनें, उनका समय लें और I ज्ञात करें।', 'ಒಂದು ದ್ರವ್ಯರಾಶಿ ಅಕ್ಷದಿಂದ ದಾರ ಬಿಚ್ಚಲು ಬಿಡಿ, ದಾರ ಜಾರಿದ ನಂತರ ಚಕ್ರದ ಸುತ್ತುಗಳನ್ನು ಎಣಿಸಿ, ಸಮಯ ಅಳೆದು I ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To determine the moment of inertia of a flywheel about its axis of rotation.', 'गतिपालक चक्र का उसके घूर्णन अक्ष के परितः जड़त्व आघूर्ण ज्ञात करना।', 'ಫ್ಲೈವೀಲ್‌ನ ಭ್ರಮಣ ಅಕ್ಷದ ಸುತ್ತ ಜಡತ್ವ ಭ್ರಾಮಕ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('The falling mass loses mgh, which becomes ½Iω² + ½mv² and the work against friction over n₁ turns. After the cord leaves, the wheel stops in n₂ turns, so friction per turn is ½Iω²/n₂. With ω = 4πn₂/t: I = m(2gh − ω²r²) / (ω²(1 + n₁/n₂)).', 'गिरता द्रव्यमान mgh खोता है, जो ½Iω² + ½mv² और n₁ चक्करों में घर्षण के विरुद्ध कार्य बनता है। डोरी छूटने के बाद चक्र n₂ चक्करों में रुकता है, अतः प्रति चक्कर घर्षण ½Iω²/n₂ है। ω = 4πn₂/t लेकर: I = m(2gh − ω²r²) / (ω²(1 + n₁/n₂))।', 'ಬೀಳುವ ದ್ರವ್ಯರಾಶಿ mgh ಕಳೆದುಕೊಳ್ಳುತ್ತದೆ; ಅದು ½Iω² + ½mv² ಮತ್ತು n₁ ಸುತ್ತುಗಳಲ್ಲಿ ಘರ್ಷಣೆಯ ವಿರುದ್ಧ ಕಾರ್ಯವಾಗುತ್ತದೆ. ದಾರ ಬಿಟ್ಟ ನಂತರ ಚಕ್ರ n₂ ಸುತ್ತುಗಳಲ್ಲಿ ನಿಲ್ಲುತ್ತದೆ, ಹಾಗಾಗಿ ಪ್ರತಿ ಸುತ್ತಿನ ಘರ್ಷಣೆ ½Iω²/n₂. ω = 4πn₂/t ಆದಾಗ: I = m(2gh − ω²r²) / (ω²(1 + n₁/n₂)).'),
        apparatus=[W('Flywheel on a wall bracket', 'दीवार ब्रैकेट पर गतिपालक चक्र', 'ಗೋಡೆ ಬ್ರ್ಯಾಕೆಟ್ ಮೇಲಿನ ಫ್ಲೈವೀಲ್'), W('Slotted masses and a cord', 'खाँचेदार बाट और डोरी', 'ಸೀಳು ತೂಕಗಳು ಮತ್ತು ದಾರ'), W('Stopwatch', 'विराम घड़ी', 'ನಿಲುಗಡಿಯಾರ'), W('Vernier callipers (for the axle)', 'वर्नियर कैलिपर्स (धुरी के लिए)', 'ವರ್ನಿಯರ್ ಕ್ಯಾಲಿಪರ್ಸ್ (ಅಕ್ಷಕ್ಕೆ)')],
        steps=[W('Measure the axle’s radius r; mark a point on the rim.', 'धुरी की त्रिज्या r मापें; परिधि पर एक बिंदु अंकित करें।', 'ಅಕ್ಷದ ತ್ರಿಜ್ಯ r ಅಳೆಯಿರಿ; ಅಂಚಿನಲ್ಲಿ ಒಂದು ಬಿಂದು ಗುರುತಿಸಿ.'),
               W('Wind the cord n₁ times round the axle with the mass hanging so it just slips off at the floor.', 'द्रव्यमान लटकाकर डोरी को धुरी पर n₁ बार लपेटें ताकि वह फ़र्श पर पहुँचकर छूट जाए।', 'ದ್ರವ್ಯರಾಶಿ ತೂಗುತ್ತಿರುವಂತೆ ದಾರವನ್ನು ಅಕ್ಷಕ್ಕೆ n₁ ಬಾರಿ ಸುತ್ತಿ, ನೆಲ ತಲುಪಿದಾಗ ಜಾರುವಂತೆ ಮಾಡಿ.'),
               W('Release the mass; when the cord slips off, start the stopwatch and count the turns n₂ until the wheel stops.', 'द्रव्यमान छोड़ें; डोरी छूटते ही विराम घड़ी चालू करें और चक्र रुकने तक चक्कर n₂ गिनें।', 'ದ್ರವ್ಯರಾಶಿ ಬಿಡಿ; ದಾರ ಜಾರಿದಾಗ ನಿಲುಗಡಿಯಾರ ಆರಂಭಿಸಿ, ಚಕ್ರ ನಿಲ್ಲುವವರೆಗೆ ಸುತ್ತುಗಳು n₂ ಎಣಿಸಿ.'),
               W('Repeat with other masses and other n₁.', 'अन्य द्रव्यमानों और अन्य n₁ के साथ दोहराएँ।', 'ಬೇರೆ ದ್ರವ್ಯರಾಶಿಗಳು ಮತ್ತು ಬೇರೆ n₁ ನೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ.'),
               W('Work out h = 2πrn₁, ω = 4πn₂/t and I for each run; take the mean.', 'हर बार h = 2πrn₁, ω = 4πn₂/t और I निकालें; माध्य लें।', 'ಪ್ರತಿ ಓಟಕ್ಕೆ h = 2πrn₁, ω = 4πn₂/t ಮತ್ತು I ಲೆಕ್ಕಿಸಿ; ಸರಾಸರಿ ತೆಗೆಯಿರಿ.')],
        precautions=[W('The cord must leave the axle exactly as the mass reaches the floor.', 'द्रव्यमान फ़र्श पर पहुँचते ही डोरी धुरी से ठीक उसी समय छूटनी चाहिए।', 'ದ್ರವ್ಯರಾಶಿ ನೆಲ ತಲುಪುವಾಗಲೇ ದಾರ ಅಕ್ಷದಿಂದ ಜಾರಬೇಕು.'), W('Wind the cord evenly, without overlapping.', 'डोरी समान रूप से, बिना एक-दूसरे पर चढ़ाए लपेटें।', 'ದಾರವನ್ನು ಮೇಲ್ಮೇಲೆ ಬಾರದಂತೆ ಸಮವಾಗಿ ಸುತ್ತಿ.')],
        conclusion=W('Different masses and windings give the same moment of inertia within error: I is a property of the wheel and its axis, not of how it is set turning.', 'विभिन्न द्रव्यमानों और लपेटों से त्रुटि सीमा में समान जड़त्व आघूर्ण मिलता है: I चक्र और उसके अक्ष का गुण है, उसे घुमाने के तरीके का नहीं।', 'ಬೇರೆ ದ್ರವ್ಯರಾಶಿಗಳು ಮತ್ತು ಸುತ್ತುಗಳು ದೋಷದೊಳಗೆ ಒಂದೇ ಜಡತ್ವ ಭ್ರಾಮಕ ನೀಡುತ್ತವೆ: I ಚಕ್ರ ಮತ್ತು ಅದರ ಅಕ್ಷದ ಗುಣ, ತಿರುಗಿಸುವ ರೀತಿಯದಲ್ಲ.'),
        viva=[Q(W('What is moment of inertia?', 'जड़त्व आघूर्ण क्या है?', 'ಜಡತ್ವ ಭ್ರಾಮಕ ಎಂದರೇನು?'), W('The rotational analogue of mass: I = Σmr², the resistance to change of rotation.', 'द्रव्यमान का घूर्णी समरूप: I = Σmr², घूर्णन में परिवर्तन का विरोध।', 'ದ್ರವ್ಯರಾಶಿಯ ಭ್ರಮಣ ಸಮಾನ: I = Σmr², ಭ್ರಮಣ ಬದಲಾವಣೆಗೆ ಪ್ರತಿರೋಧ.')),
              Q(W('Why is most of a flywheel’s mass in its rim?', 'गतिपालक चक्र का अधिकांश द्रव्यमान परिधि में क्यों होता है?', 'ಫ್ಲೈವೀಲ್‌ನ ಹೆಚ್ಚಿನ ದ್ರವ್ಯರಾಶಿ ಅಂಚಿನಲ್ಲಿ ಏಕೆ?'), W('Mass far from the axis gives a large I for little total mass.', 'अक्ष से दूर द्रव्यमान कम कुल द्रव्यमान में अधिक I देता है।', 'ಅಕ್ಷದಿಂದ ದೂರದ ದ್ರವ್ಯರಾಶಿ ಕಡಿಮೆ ಒಟ್ಟು ದ್ರವ್ಯರಾಶಿಗೆ ಹೆಚ್ಚು I ನೀಡುತ್ತದೆ.')),
              Q(W('Why is ω = 4πn₂/t?', 'ω = 4πn₂/t क्यों है?', 'ω = 4πn₂/t ಏಕೆ?'), W('The wheel slows uniformly, so its average speed 2πn₂/t is half the starting ω.', 'चक्र एकसमान रूप से धीमा होता है, अतः उसकी औसत चाल 2πn₂/t प्रारंभिक ω की आधी है।', 'ಚಕ್ರ ಏಕರೂಪವಾಗಿ ನಿಧಾನವಾಗುತ್ತದೆ; ಅದರ ಸರಾಸರಿ ವೇಗ 2πn₂/t ಆರಂಭಿಕ ω ನ ಅರ್ಧ.')),
              Q(W('Where are flywheels used?', 'गतिपालक चक्र कहाँ उपयोग होते हैं?', 'ಫ್ಲೈವೀಲ್‌ಗಳನ್ನು ಎಲ್ಲಿ ಬಳಸುತ್ತಾರೆ?'), W('In engines and sewing machines, to keep the rotation steady between strokes.', 'इंजनों और सिलाई मशीनों में, झटकों के बीच घूर्णन स्थिर रखने के लिए।', 'ಎಂಜಿನ್‌ಗಳು ಮತ್ತು ಹೊಲಿಗೆ ಯಂತ್ರಗಳಲ್ಲಿ, ಹೊಡೆತಗಳ ನಡುವೆ ಭ್ರಮಣ ಸ್ಥಿರವಾಗಿಡಲು.')),
              Q(W('What is the SI unit of moment of inertia?', 'जड़त्व आघूर्ण का SI मात्रक क्या है?', 'ಜಡತ್ವ ಭ್ರಾಮಕದ SI ಏಕಮಾನ ಯಾವುದು?'), W('kg m².', 'kg m².', 'kg m².'))])

    # ------------------------------------------------------- galvanometer
    lab(id='galvanometer-half-deflection', bench='galvanometer', **puc2,
        keywords=['galvanometer', 'half deflection', 'figure of merit', 'resistance of a galvanometer', 'moving charges and magnetism', 'moving coil galvanometer'],
        title=W('Resistance and figure of merit of a galvanometer', 'धारामापी का प्रतिरोध और दक्षतांक', 'ಗ್ಯಾಲ್ವನೋಮೀಟರ್‌ನ ರೋಧ ಮತ್ತು ಗುಣಾಂಕ'),
        summary=W('Note a deflection θ through a high resistance, then shunt the galvanometer until it reads θ/2: G = RS/(R − S).', 'उच्च प्रतिरोध से विक्षेप θ लें, फिर धारामापी को शंट करें जब तक वह θ/2 न दिखाए: G = RS/(R − S)।', 'ಹೆಚ್ಚಿನ ರೋಧದ ಮೂಲಕ ವಿಚಲನ θ ಗಮನಿಸಿ, ನಂತರ θ/2 ತೋರುವವರೆಗೆ ಗ್ಯಾಲ್ವನೋಮೀಟರ್‌ಗೆ ಶಂಟ್ ಹಾಕಿ: G = RS/(R − S).'),
        aim=W('To determine the resistance of a galvanometer by the half-deflection method and to find its figure of merit.', 'अर्ध-विक्षेप विधि से धारामापी का प्रतिरोध ज्ञात करना और उसका दक्षतांक निकालना।', 'ಅರ್ಧ ವಿಚಲನ ವಿಧಾನದಿಂದ ಗ್ಯಾಲ್ವನೋಮೀಟರ್‌ನ ರೋಧ ಮತ್ತು ಅದರ ಗುಣಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('With K₂ open, I = E/(R + G) gives deflection θ. A shunt S across G that halves the deflection, with R ≫ G, gives G = RS/(R − S). The figure of merit, the current per division, is k = E/((R + G)θ).', 'K₂ खुली होने पर I = E/(R + G) से विक्षेप θ मिलता है। G के समांतर शंट S जो विक्षेप आधा कर दे, R ≫ G होने पर, G = RS/(R − S) देता है। दक्षतांक, प्रति भाग धारा, k = E/((R + G)θ) है।', 'K₂ ತೆರೆದಾಗ I = E/(R + G) ವಿಚಲನ θ ನೀಡುತ್ತದೆ. G ಗೆ ಸಮಾಂತರವಾಗಿ ವಿಚಲನವನ್ನು ಅರ್ಧಗೊಳಿಸುವ ಶಂಟ್ S, R ≫ G ಆದಾಗ, G = RS/(R − S) ನೀಡುತ್ತದೆ. ಗುಣಾಂಕ, ಪ್ರತಿ ವಿಭಾಗದ ಪ್ರವಾಹ, k = E/((R + G)θ).'),
        apparatus=[GALV, BATTERY, RBOX, PLUGKEY],
        steps=[W('Connect the cell, K₁, the high resistance R and the galvanometer in series; S with K₂ across G.', 'सेल, K₁, उच्च प्रतिरोध R और धारामापी को श्रेणी में जोड़ें; G के समांतर K₂ सहित S।', 'ಕೋಶ, K₁, ಹೆಚ್ಚಿನ ರೋಧ R ಮತ್ತು ಗ್ಯಾಲ್ವನೋಮೀಟರನ್ನು ಸರಣಿಯಲ್ಲಿ ಜೋಡಿಸಿ; G ಗೆ ಸಮಾಂತರವಾಗಿ K₂ ಸಹಿತ S.'),
               W('Take out a large R, close K₁ and adjust R for an even deflection θ near 20–30 divisions.', 'बड़ा R निकालें, K₁ बंद करें और 20–30 भाग के आसपास सम विक्षेप θ के लिए R समायोजित करें।', 'ದೊಡ್ಡ R ತೆಗೆದು K₁ ಮುಚ್ಚಿ, 20–30 ವಿಭಾಗಗಳ ಹತ್ತಿರ ಸಮ ವಿಚಲನ θ ಗಾಗಿ R ಹೊಂದಿಸಿ.'),
               W('Close K₂ and adjust S until the deflection is exactly θ/2.', 'K₂ बंद करें और S को तब तक समायोजित करें जब तक विक्षेप ठीक θ/2 न हो।', 'K₂ ಮುಚ್ಚಿ ವಿಚಲನ ನಿಖರವಾಗಿ θ/2 ಆಗುವವರೆಗೆ S ಹೊಂದಿಸಿ.'),
               W('Record R, θ and S; repeat for four more values of R.', 'R, θ और S लिखें; R के चार और मानों के लिए दोहराएँ।', 'R, θ ಮತ್ತು S ದಾಖಲಿಸಿ; R ನ ಇನ್ನೂ ನಾಲ್ಕು ಮೌಲ್ಯಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ.'),
               W('Work out G = RS/(R − S) and k = E/((R + G)θ) for each, and take the means.', 'प्रत्येक के लिए G = RS/(R − S) और k = E/((R + G)θ) निकालें और माध्य लें।', 'ಪ್ರತಿಯೊಂದಕ್ಕೆ G = RS/(R − S) ಮತ್ತು k = E/((R + G)θ) ಲೆಕ್ಕಿಸಿ ಸರಾಸರಿ ತೆಗೆಯಿರಿ.')],
        precautions=[W('Start with a large R so the galvanometer is not damaged.', 'बड़े R से शुरू करें ताकि धारामापी क्षतिग्रस्त न हो।', 'ಗ್ಯಾಲ್ವನೋಮೀಟರ್ ಹಾಳಾಗದಂತೆ ದೊಡ್ಡ R ನಿಂದ ಆರಂಭಿಸಿ.'), W('Choose θ even so that θ/2 is a whole number of divisions.', 'θ सम चुनें ताकि θ/2 पूर्ण भाग हो।', 'θ/2 ಪೂರ್ಣ ವಿಭಾಗವಾಗುವಂತೆ θ ಸಮವಾಗಿ ಆರಿಸಿ.'), KEYS],
        conclusion=W('The galvanometer’s resistance comes out close to 96 Ω and its figure of merit close to 2 × 10⁻⁵ A per division.', 'धारामापी का प्रतिरोध लगभग 96 Ω और दक्षतांक लगभग 2 × 10⁻⁵ A प्रति भाग आता है।', 'ಗ್ಯಾಲ್ವನೋಮೀಟರ್‌ನ ರೋಧ ಸುಮಾರು 96 Ω ಮತ್ತು ಗುಣಾಂಕ ಸುಮಾರು 2 × 10⁻⁵ A ಪ್ರತಿ ವಿಭಾಗ ಬರುತ್ತದೆ.'),
        viva=[Q(W('What is the figure of merit of a galvanometer?', 'धारामापी का दक्षतांक क्या है?', 'ಗ್ಯಾಲ್ವನೋಮೀಟರ್‌ನ ಗುಣಾಂಕ ಎಂದರೇನು?'), W('The current that gives a deflection of one division.', 'वह धारा जो एक भाग का विक्षेप देती है।', 'ಒಂದು ವಿಭಾಗದ ವಿಚಲನ ನೀಡುವ ಪ್ರವಾಹ.')),
              Q(W('Why must R be much larger than G?', 'R को G से बहुत बड़ा क्यों होना चाहिए?', 'R, G ಗಿಂತ ತುಂಬಾ ದೊಡ್ಡದಾಗಿರಬೇಕು ಏಕೆ?'), W('So the total current hardly changes when the shunt is added; then G = RS/(R − S) holds.', 'ताकि शंट जोड़ने पर कुल धारा लगभग न बदले; तब G = RS/(R − S) लागू होता है।', 'ಶಂಟ್ ಸೇರಿಸಿದಾಗ ಒಟ್ಟು ಪ್ರವಾಹ ಹೆಚ್ಚು ಬದಲಾಗದಂತೆ; ಆಗ G = RS/(R − S) ಸರಿ.')),
              Q(W('What is a shunt?', 'शंट क्या है?', 'ಶಂಟ್ ಎಂದರೇನು?'), W('A low resistance connected in parallel with a galvanometer.', 'धारामापी के समांतर जुड़ा एक कम प्रतिरोध।', 'ಗ್ಯಾಲ್ವನೋಮೀಟರ್‌ಗೆ ಸಮಾಂತರವಾಗಿ ಜೋಡಿಸಿದ ಕಡಿಮೆ ರೋಧ.')),
              Q(W('Why is the coil wound on a soft-iron core in a radial field?', 'कुंडली नरम लोहे के कोर पर त्रिज्य क्षेत्र में क्यों लपेटी जाती है?', 'ಸುರುಳಿಯನ್ನು ಮೃದು ಕಬ್ಬಿಣದ ತಿರುಳಿನ ಮೇಲೆ ತ್ರಿಜ್ಯ ಕ್ಷೇತ್ರದಲ್ಲಿ ಏಕೆ ಸುತ್ತುತ್ತಾರೆ?'), W('So the deflection is proportional to the current (a linear scale).', 'ताकि विक्षेप धारा के अनुक्रमानुपाती हो (रैखिक पैमाना)।', 'ವಿಚಲನ ಪ್ರವಾಹಕ್ಕೆ ಅನುಪಾತೀಯವಾಗಲು (ರೇಖೀಯ ಅಳತೆ).')),
              Q(W('What is the current sensitivity?', 'धारा सुग्राहिता क्या है?', 'ಪ್ರವಾಹ ಸಂವೇದನೆ ಎಂದರೇನು?'), W('Deflection per unit current, θ/I = 1/k.', 'प्रति इकाई धारा विक्षेप, θ/I = 1/k।', 'ಏಕಮಾನ ಪ್ರವಾಹಕ್ಕೆ ವಿಚಲನ, θ/I = 1/k.'))])

    lab(id='galvanometer-voltmeter', bench='galv-voltmeter', **puc2,
        keywords=['galvanometer', 'conversion into voltmeter', 'voltmeter', 'series resistance', 'moving charges and magnetism'],
        title=W('Converting a galvanometer into a voltmeter', 'धारामापी को वोल्टमीटर में बदलना', 'ಗ್ಯಾಲ್ವನೋಮೀಟರನ್ನು ವೋಲ್ಟ್‌ಮೀಟರ್ ಆಗಿ ಪರಿವರ್ತಿಸುವುದು'),
        summary=W('Put R = V/Ig − G in series with the galvanometer and check the new voltmeter against a standard one.', 'धारामापी के श्रेणी में R = V/Ig − G लगाएँ और नए वोल्टमीटर को मानक वोल्टमीटर से जाँचें।', 'ಗ್ಯಾಲ್ವನೋಮೀಟರ್‌ಗೆ ಸರಣಿಯಲ್ಲಿ R = V/Ig − G ಹಾಕಿ, ಹೊಸ ವೋಲ್ಟ್‌ಮೀಟರನ್ನು ಪ್ರಮಾಣಿತ ವೋಲ್ಟ್‌ಮೀಟರ್‌ನಿಂದ ಪರೀಕ್ಷಿಸಿ.'),
        aim=W('To convert a galvanometer of known resistance and figure of merit into a voltmeter of a given range and to verify it.', 'ज्ञात प्रतिरोध और दक्षतांक वाले धारामापी को दिए गए परास के वोल्टमीटर में बदलना और सत्यापित करना।', 'ತಿಳಿದ ರೋಧ ಮತ್ತು ಗುಣಾಂಕದ ಗ್ಯಾಲ್ವನೋಮೀಟರನ್ನು ನೀಡಿದ ವ್ಯಾಪ್ತಿಯ ವೋಲ್ಟ್‌ಮೀಟರ್ ಆಗಿ ಪರಿವರ್ತಿಸಿ ಪರಿಶೀಲಿಸುವುದು.'),
        principle=W('Full-scale current Ig = 30k. A high resistance R in series makes the full-scale voltage V = Ig(G + R), so R = V/Ig − G. Each division then stands for V/30 volts.', 'पूर्ण पैमाना धारा Ig = 30k. श्रेणी में उच्च प्रतिरोध R पूर्ण पैमाना वोल्टता V = Ig(G + R) बनाता है, अतः R = V/Ig − G. तब प्रत्येक भाग V/30 वोल्ट दर्शाता है।', 'ಪೂರ್ಣ ಅಳತೆ ಪ್ರವಾಹ Ig = 30k. ಸರಣಿಯಲ್ಲಿನ ಹೆಚ್ಚಿನ ರೋಧ R ಪೂರ್ಣ ಅಳತೆ ವೋಲ್ಟೇಜ್ V = Ig(G + R) ಮಾಡುತ್ತದೆ, ಆದ್ದರಿಂದ R = V/Ig − G. ಆಗ ಪ್ರತಿ ವಿಭಾಗ V/30 ವೋಲ್ಟ್.'),
        apparatus=[GALV, W('Standard voltmeter', 'मानक वोल्टमीटर', 'ಪ್ರಮಾಣಿತ ವೋಲ್ಟ್‌ಮೀಟರ್'), RBOX, W('Rheostat, battery and key', 'धारा नियंत्रक, बैटरी और कुंजी', 'ರಿಯೋಸ್ಟಾಟ್, ಬ್ಯಾಟರಿ ಮತ್ತು ಕೀಲಿ')],
        steps=[W('From G and k work out Ig and the series resistance R for the range wanted.', 'G और k से Ig और वांछित परास के लिए श्रेणी प्रतिरोध R निकालें।', 'G ಮತ್ತು k ಯಿಂದ Ig ಮತ್ತು ಬೇಕಾದ ವ್ಯಾಪ್ತಿಗೆ ಸರಣಿ ರೋಧ R ಲೆಕ್ಕಿಸಿ.'),
               W('Take R out of the resistance box in series with the galvanometer.', 'धारामापी के श्रेणी में प्रतिरोध बॉक्स से R निकालें।', 'ಗ್ಯಾಲ್ವನೋಮೀಟರ್‌ಗೆ ಸರಣಿಯಲ್ಲಿನ ರೋಧ ಪೆಟ್ಟಿಗೆಯಿಂದ R ತೆಗೆಯಿರಿ.'),
               W('Connect this combination in parallel with the standard voltmeter across the rheostat.', 'इस संयोजन को धारा नियंत्रक पर मानक वोल्टमीटर के समांतर जोड़ें।', 'ಈ ಸಂಯೋಜನೆಯನ್ನು ರಿಯೋಸ್ಟಾಟ್‌ಗೆ ಅಡ್ಡಲಾಗಿ ಪ್ರಮಾಣಿತ ವೋಲ್ಟ್‌ಮೀಟರ್‌ನೊಂದಿಗೆ ಸಮಾಂತರವಾಗಿ ಜೋಡಿಸಿ.'),
               W('Change the voltage in steps; record the standard reading and θ.', 'वोल्टता चरणों में बदलें; मानक पाठ्यांक और θ लिखें।', 'ವೋಲ್ಟೇಜನ್ನು ಹಂತಗಳಲ್ಲಿ ಬದಲಿಸಿ; ಪ್ರಮಾಣಿತ ಓದು ಮತ್ತು θ ದಾಖಲಿಸಿ.'),
               W('Compare V = θ × V₀/30 with the standard voltmeter.', 'V = θ × V₀/30 की तुलना मानक वोल्टमीटर से करें।', 'V = θ × V₀/30 ಅನ್ನು ಪ್ರಮಾಣಿತ ವೋಲ್ಟ್‌ಮೀಟರ್‌ನೊಂದಿಗೆ ಹೋಲಿಸಿ.')],
        precautions=[W('Never connect the galvanometer across the supply without the series resistance.', 'श्रेणी प्रतिरोध के बिना धारामापी को स्रोत के आर-पार कभी न जोड़ें।', 'ಸರಣಿ ರೋಧವಿಲ್ಲದೆ ಗ್ಯಾಲ್ವನೋಮೀಟರನ್ನು ಸರಬರಾಜಿಗೆ ಎಂದೂ ಜೋಡಿಸಬೇಡಿ.'), WIRES, KEYS],
        conclusion=W('With R = V/Ig − G in series, the galvanometer reads voltage in step with the standard voltmeter: it has become a voltmeter of the chosen range.', 'श्रेणी में R = V/Ig − G के साथ धारामापी मानक वोल्टमीटर के साथ वोल्टता पढ़ता है: वह चुने गए परास का वोल्टमीटर बन गया है।', 'ಸರಣಿಯಲ್ಲಿ R = V/Ig − G ಇರುವಾಗ ಗ್ಯಾಲ್ವನೋಮೀಟರ್ ಪ್ರಮಾಣಿತ ವೋಲ್ಟ್‌ಮೀಟರ್ ಜೊತೆಗೆ ವೋಲ್ಟೇಜ್ ಓದುತ್ತದೆ: ಅದು ಆಯ್ದ ವ್ಯಾಪ್ತಿಯ ವೋಲ್ಟ್‌ಮೀಟರ್ ಆಗಿದೆ.'),
        viva=[Q(W('Why is a high resistance put in series?', 'श्रेणी में उच्च प्रतिरोध क्यों लगाते हैं?', 'ಸರಣಿಯಲ್ಲಿ ಹೆಚ್ಚಿನ ರೋಧ ಏಕೆ?'), W('To limit the current to Ig at full-scale voltage and to draw little current from the circuit.', 'पूर्ण पैमाना वोल्टता पर धारा को Ig तक सीमित करने और परिपथ से कम धारा लेने के लिए।', 'ಪೂರ್ಣ ಅಳತೆ ವೋಲ್ಟೇಜ್‌ನಲ್ಲಿ ಪ್ರವಾಹವನ್ನು Ig ಗೆ ಮಿತಿಗೊಳಿಸಲು ಮತ್ತು ಮಂಡಲದಿಂದ ಕಡಿಮೆ ಪ್ರವಾಹ ತೆಗೆದುಕೊಳ್ಳಲು.')),
              Q(W('What is the resistance of an ideal voltmeter?', 'आदर्श वोल्टमीटर का प्रतिरोध क्या है?', 'ಆದರ್ಶ ವೋಲ್ಟ್‌ಮೀಟರ್‌ನ ರೋಧ ಎಷ್ಟು?'), W('Infinite.', 'अनंत।', 'ಅನಂತ.')),
              Q(W('How is a voltmeter connected?', 'वोल्टमीटर कैसे जोड़ा जाता है?', 'ವೋಲ್ಟ್‌ಮೀಟರನ್ನು ಹೇಗೆ ಜೋಡಿಸುತ್ತಾರೆ?'), W('In parallel with the part whose potential difference is wanted.', 'उस भाग के समांतर जिसका विभवांतर चाहिए।', 'ವಿಭವಾಂತರ ಬೇಕಾದ ಭಾಗಕ್ಕೆ ಸಮಾಂತರವಾಗಿ.')),
              Q(W('To double the range, what happens to R?', 'परास दोगुना करने के लिए R का क्या होता है?', 'ವ್ಯಾಪ್ತಿ ಎರಡು ಪಟ್ಟು ಮಾಡಲು R ಏನಾಗುತ್ತದೆ?'), W('It becomes 2V/Ig − G: a little more than double.', 'यह 2V/Ig − G हो जाता है: दोगुने से थोड़ा अधिक।', 'ಅದು 2V/Ig − G ಆಗುತ್ತದೆ: ಎರಡು ಪಟ್ಟಿಗಿಂತ ಸ್ವಲ್ಪ ಹೆಚ್ಚು.')),
              Q(W('What is Ig here?', 'यहाँ Ig क्या है?', 'ಇಲ್ಲಿ Ig ಎಷ್ಟು?'), W('30 divisions × 2 × 10⁻⁵ A = 6 × 10⁻⁴ A.', '30 भाग × 2 × 10⁻⁵ A = 6 × 10⁻⁴ A.', '30 ವಿಭಾಗ × 2 × 10⁻⁵ A = 6 × 10⁻⁴ A.'))])

    lab(id='galvanometer-ammeter', bench='galv-ammeter', **puc2,
        keywords=['galvanometer', 'conversion into ammeter', 'ammeter', 'shunt', 'moving charges and magnetism'],
        title=W('Converting a galvanometer into an ammeter', 'धारामापी को ऐमीटर में बदलना', 'ಗ್ಯಾಲ್ವನೋಮೀಟರನ್ನು ಅಮ್ಮೀಟರ್ ಆಗಿ ಪರಿವರ್ತಿಸುವುದು'),
        summary=W('Put a shunt S = IgG/(I − Ig) across the galvanometer and check the new ammeter against a standard one.', 'धारामापी के समांतर शंट S = IgG/(I − Ig) लगाएँ और नए ऐमीटर को मानक ऐमीटर से जाँचें।', 'ಗ್ಯಾಲ್ವನೋಮೀಟರ್‌ಗೆ ಅಡ್ಡಲಾಗಿ ಶಂಟ್ S = IgG/(I − Ig) ಹಾಕಿ, ಹೊಸ ಅಮ್ಮೀಟರನ್ನು ಪ್ರಮಾಣಿತ ಅಮ್ಮೀಟರ್‌ನಿಂದ ಪರೀಕ್ಷಿಸಿ.'),
        aim=W('To convert a galvanometer into an ammeter of a given range and to verify it.', 'धारामापी को दिए गए परास के ऐमीटर में बदलना और सत्यापित करना।', 'ಗ್ಯಾಲ್ವನೋಮೀಟರನ್ನು ನೀಡಿದ ವ್ಯಾಪ್ತಿಯ ಅಮ್ಮೀಟರ್ ಆಗಿ ಪರಿವರ್ತಿಸಿ ಪರಿಶೀಲಿಸುವುದು.'),
        principle=W('A low resistance S across G carries most of the current: IgG = (I − Ig)S, so S = IgG/(I − Ig). Each division then stands for I/30.', 'G के समांतर कम प्रतिरोध S अधिकांश धारा ले जाता है: IgG = (I − Ig)S, अतः S = IgG/(I − Ig). तब प्रत्येक भाग I/30 दर्शाता है।', 'G ಗೆ ಅಡ್ಡಲಾಗಿನ ಕಡಿಮೆ ರೋಧ S ಹೆಚ್ಚಿನ ಪ್ರವಾಹ ಸಾಗಿಸುತ್ತದೆ: IgG = (I − Ig)S, ಆದ್ದರಿಂದ S = IgG/(I − Ig). ಆಗ ಪ್ರತಿ ವಿಭಾಗ I/30.'),
        apparatus=[GALV, W('Standard milliammeter', 'मानक मिलीऐमीटर', 'ಪ್ರಮಾಣಿತ ಮಿಲಿಅಮ್ಮೀಟರ್'), W('Shunt wire or low resistance box', 'शंट तार या कम प्रतिरोध बॉक्स', 'ಶಂಟ್ ತಂತಿ ಅಥವಾ ಕಡಿಮೆ ರೋಧ ಪೆಟ್ಟಿಗೆ'), W('Rheostat, battery and key', 'धारा नियंत्रक, बैटरी और कुंजी', 'ರಿಯೋಸ್ಟಾಟ್, ಬ್ಯಾಟರಿ ಮತ್ತು ಕೀಲಿ')],
        steps=[W('Work out the shunt S for the range wanted from G and Ig.', 'G और Ig से वांछित परास के लिए शंट S निकालें।', 'G ಮತ್ತು Ig ಯಿಂದ ಬೇಕಾದ ವ್ಯಾಪ್ತಿಗೆ ಶಂಟ್ S ಲೆಕ್ಕಿಸಿ.'),
               W('Connect S across the galvanometer.', 'S को धारामापी के समांतर जोड़ें।', 'S ಅನ್ನು ಗ್ಯಾಲ್ವನೋಮೀಟರ್‌ಗೆ ಅಡ್ಡಲಾಗಿ ಜೋಡಿಸಿ.'),
               W('Join the converted ammeter in series with the standard ammeter, rheostat, battery and key.', 'परिवर्तित ऐमीटर को मानक ऐमीटर, धारा नियंत्रक, बैटरी और कुंजी के साथ श्रेणी में जोड़ें।', 'ಪರಿವರ್ತಿತ ಅಮ್ಮೀಟರನ್ನು ಪ್ರಮಾಣಿತ ಅಮ್ಮೀಟರ್, ರಿಯೋಸ್ಟಾಟ್, ಬ್ಯಾಟರಿ ಮತ್ತು ಕೀಲಿಯೊಂದಿಗೆ ಸರಣಿಯಲ್ಲಿ ಜೋಡಿಸಿ.'),
               W('Change the current in steps; record the standard reading and θ.', 'धारा चरणों में बदलें; मानक पाठ्यांक और θ लिखें।', 'ಪ್ರವಾಹವನ್ನು ಹಂತಗಳಲ್ಲಿ ಬದಲಿಸಿ; ಪ್ರಮಾಣಿತ ಓದು ಮತ್ತು θ ದಾಖಲಿಸಿ.'),
               W('Compare I = θ × I₀/30 with the standard ammeter.', 'I = θ × I₀/30 की तुलना मानक ऐमीटर से करें।', 'I = θ × I₀/30 ಅನ್ನು ಪ್ರಮಾಣಿತ ಅಮ್ಮೀಟರ್‌ನೊಂದಿಗೆ ಹೋಲಿಸಿ.')],
        precautions=[W('Fix the shunt before the current is switched on.', 'धारा चालू करने से पहले शंट लगा दें।', 'ಪ್ರವಾಹ ಆರಂಭಿಸುವ ಮೊದಲೇ ಶಂಟ್ ಜೋಡಿಸಿ.'), W('Keep the rheostat at maximum resistance when starting.', 'आरंभ में धारा नियंत्रक अधिकतम प्रतिरोध पर रखें।', 'ಆರಂಭದಲ್ಲಿ ರಿಯೋಸ್ಟಾಟನ್ನು ಗರಿಷ್ಠ ರೋಧದಲ್ಲಿಡಿ.'), WIRES],
        conclusion=W('With the shunt S = IgG/(I − Ig) across it, the galvanometer follows the standard ammeter over the whole range: it has become an ammeter.', 'समांतर में शंट S = IgG/(I − Ig) के साथ धारामापी पूरे परास में मानक ऐमीटर का अनुसरण करता है: वह ऐमीटर बन गया है।', 'ಅಡ್ಡಲಾಗಿ ಶಂಟ್ S = IgG/(I − Ig) ಇರುವಾಗ ಗ್ಯಾಲ್ವನೋಮೀಟರ್ ಸಂಪೂರ್ಣ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ ಪ್ರಮಾಣಿತ ಅಮ್ಮೀಟರನ್ನು ಅನುಸರಿಸುತ್ತದೆ: ಅದು ಅಮ್ಮೀಟರ್ ಆಗಿದೆ.'),
        viva=[Q(W('Why is the shunt resistance small?', 'शंट प्रतिरोध छोटा क्यों होता है?', 'ಶಂಟ್ ರೋಧ ಸಣ್ಣದು ಏಕೆ?'), W('So nearly all the current bypasses the delicate coil.', 'ताकि लगभग सारी धारा नाज़ुक कुंडली को छोड़कर निकले।', 'ಬಹುತೇಕ ಎಲ್ಲಾ ಪ್ರವಾಹ ಸೂಕ್ಷ್ಮ ಸುರುಳಿಯನ್ನು ತಪ್ಪಿಸಿ ಹೋಗಲು.')),
              Q(W('What is the resistance of an ideal ammeter?', 'आदर्श ऐमीटर का प्रतिरोध क्या है?', 'ಆದರ್ಶ ಅಮ್ಮೀಟರ್‌ನ ರೋಧ ಎಷ್ಟು?'), W('Zero.', 'शून्य।', 'ಶೂನ್ಯ.')),
              Q(W('How is an ammeter connected?', 'ऐमीटर कैसे जोड़ा जाता है?', 'ಅಮ್ಮೀಟರನ್ನು ಹೇಗೆ ಜೋಡಿಸುತ್ತಾರೆ?'), W('In series with the circuit.', 'परिपथ के श्रेणी में।', 'ಮಂಡಲಕ್ಕೆ ಸರಣಿಯಲ್ಲಿ.')),
              Q(W('What is the converted ammeter’s resistance?', 'परिवर्तित ऐमीटर का प्रतिरोध क्या है?', 'ಪರಿವರ್ತಿತ ಅಮ್ಮೀಟರ್‌ನ ರೋಧ ಎಷ್ಟು?'), W('GS/(G + S): a little less than S.', 'GS/(G + S): S से थोड़ा कम।', 'GS/(G + S): S ಗಿಂತ ಸ್ವಲ್ಪ ಕಡಿಮೆ.')),
              Q(W('For a 0–30 mA range, what shunt is needed here?', '0–30 mA परास के लिए यहाँ कितना शंट चाहिए?', '0–30 mA ವ್ಯಾಪ್ತಿಗೆ ಇಲ್ಲಿ ಎಷ್ಟು ಶಂಟ್ ಬೇಕು?'), W('S = 6 × 10⁻⁴ × 96 / (0.03 − 0.0006) ≈ 1.96 Ω.', 'S = 6 × 10⁻⁴ × 96 / (0.03 − 0.0006) ≈ 1.96 Ω.', 'S = 6 × 10⁻⁴ × 96 / (0.03 − 0.0006) ≈ 1.96 Ω.'))])

    # ---------------------------------------------------------- sonometer
    SONO_APP = [W('Sonometer with a steel wire', 'स्टील तार सहित स्वरमापी', 'ಉಕ್ಕಿನ ತಂತಿ ಸಹಿತ ಸೋನೋಮೀಟರ್'), W('Set of tuning forks', 'स्वरित्रों का सेट', 'ಶ್ರುತಿಕವೆಗಳ ಸೆಟ್'), W('Hanger with slotted masses', 'खाँचेदार बाटों सहित हैंगर', 'ಸೀಳು ತೂಕಗಳ ಸಹಿತ ಹ್ಯಾಂಗರ್'), W('Paper rider and rubber pad', 'कागज़ का सवार और रबर पैड', 'ಕಾಗದದ ಸವಾರ ಮತ್ತು ರಬ್ಬರ್ ಪ್ಯಾಡ್')]
    SONO_PRE = [W('Press the stem of the fork on the box; do not touch the prongs to it.', 'स्वरित्र का तना बॉक्स पर दबाएँ; भुजाएँ उससे न छुएँ।', 'ಶ್ರುತಿಕವೆಯ ಕಾಂಡವನ್ನು ಪೆಟ್ಟಿಗೆಯ ಮೇಲೆ ಒತ್ತಿ; ಕವಲುಗಳು ತಾಗದಿರಲಿ.'), W('Approach resonance slowly from both sides and take the mean length.', 'अनुनाद तक दोनों ओर से धीरे-धीरे पहुँचें और माध्य लंबाई लें।', 'ಅನುನಾದವನ್ನು ಎರಡೂ ಕಡೆಯಿಂದ ನಿಧಾನವಾಗಿ ತಲುಪಿ ಸರಾಸರಿ ಉದ್ದ ತೆಗೆಯಿರಿ.'), W('The wire must be free of kinks.', 'तार में मोड़ नहीं होने चाहिए।', 'ತಂತಿಯಲ್ಲಿ ತಿರುವುಗಳಿರಬಾರದು.')]
    lab(id='sonometer-law-of-length', bench='sonometer-laws', setup={'task': 'length'}, **puc1,
        keywords=['sonometer', 'law of length', 'frequency and length', 'waves', 'stationary waves', 'tuning fork', 'resonance', 'stretched string'],
        title=W('Sonometer: frequency and resonating length', 'स्वरमापी: आवृत्ति और अनुनादी लंबाई', 'ಸೋನೋಮೀಟರ್: ಆವರ್ತನ ಮತ್ತು ಅನುನಾದ ಉದ್ದ'),
        summary=W('At a fixed tension, find the length that resonates with each tuning fork; n × l stays constant.', 'नियत तनाव पर प्रत्येक स्वरित्र के साथ अनुनाद करने वाली लंबाई ढूँढें; n × l नियत रहता है।', 'ನಿಗದಿತ ಎಳೆತದಲ್ಲಿ ಪ್ರತಿ ಶ್ರುತಿಕವೆಯೊಂದಿಗೆ ಅನುನಾದಿಸುವ ಉದ್ದ ಕಂಡುಹಿಡಿಯಿರಿ; n × l ಸ್ಥಿರ.'),
        aim=W('To study the relation between the frequency and the length of a stretched wire under constant tension using a sonometer, and to find the wire’s mass per unit length.', 'स्वरमापी से नियत तनाव पर तने तार की आवृत्ति और लंबाई के बीच संबंध का अध्ययन करना और तार का प्रति इकाई लंबाई द्रव्यमान ज्ञात करना।', 'ಸೋನೋಮೀಟರ್ ಬಳಸಿ ಸ್ಥಿರ ಎಳೆತದಲ್ಲಿ ಬಿಗಿದ ತಂತಿಯ ಆವರ್ತನ ಮತ್ತು ಉದ್ದದ ಸಂಬಂಧ ಅಧ್ಯಯನ ಮಾಡಿ ಪ್ರತಿ ಏಕಮಾನ ಉದ್ದದ ದ್ರವ್ಯರಾಶಿ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('A wire of length l, tension T and mass per unit length μ vibrates in its fundamental mode at n = (1/2l)√(T/μ). At fixed T, n ∝ 1/l, so n × l is constant and the graph of n against 1/l is a straight line through the origin.', 'l लंबाई, T तनाव और μ प्रति इकाई लंबाई द्रव्यमान का तार मूल विधा में n = (1/2l)√(T/μ) पर कंपन करता है। नियत T पर n ∝ 1/l, अतः n × l नियत है और n तथा 1/l का ग्राफ़ मूल बिंदु से जाने वाली सीधी रेखा है।', 'l ಉದ್ದ, T ಎಳೆತ ಮತ್ತು μ ಪ್ರತಿ ಏಕಮಾನ ಉದ್ದದ ದ್ರವ್ಯರಾಶಿಯ ತಂತಿ ಮೂಲ ವಿಧಾನದಲ್ಲಿ n = (1/2l)√(T/μ) ನಲ್ಲಿ ಕಂಪಿಸುತ್ತದೆ. ಸ್ಥಿರ T ಯಲ್ಲಿ n ∝ 1/l; ಹಾಗಾಗಿ n × l ಸ್ಥಿರ, n ಮತ್ತು 1/l ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ ಸರಳರೇಖೆ.'),
        apparatus=SONO_APP,
        steps=[W('Hang a fixed load (say 3 kg) and place a paper rider at the middle of the wire.', 'एक नियत भार (मान लें 3 kg) लटकाएँ और तार के बीच में कागज़ का सवार रखें।', 'ನಿಗದಿತ ಭಾರ (ಉದಾ. 3 kg) ತೂಗುಹಾಕಿ ತಂತಿಯ ಮಧ್ಯದಲ್ಲಿ ಕಾಗದದ ಸವಾರ ಇಡಿ.'),
               W('Strike a fork on the pad and press its stem on the box.', 'स्वरित्र को पैड पर मारें और उसका तना बॉक्स पर दबाएँ।', 'ಶ್ರುತಿಕವೆಯನ್ನು ಪ್ಯಾಡ್‌ಗೆ ಹೊಡೆದು ಅದರ ಕಾಂಡವನ್ನು ಪೆಟ್ಟಿಗೆಯ ಮೇಲೆ ಒತ್ತಿ.'),
               W('Move the bridge until the rider flies off; record the length l.', 'सेतु खिसकाएँ जब तक सवार उड़ न जाए; लंबाई l लिखें।', 'ಸವಾರ ಹಾರಿ ಹೋಗುವವರೆಗೆ ಸೇತುವೆ ಸರಿಸಿ; ಉದ್ದ l ದಾಖಲಿಸಿ.'),
               W('Repeat with each fork at the same tension.', 'उसी तनाव पर हर स्वरित्र से दोहराएँ।', 'ಅದೇ ಎಳೆತದಲ್ಲಿ ಪ್ರತಿ ಶ್ರುತಿಕವೆಯೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ.'),
               W('Find n × l for each and plot n against 1/l.', 'प्रत्येक के लिए n × l निकालें और n तथा 1/l का ग्राफ़ बनाएँ।', 'ಪ್ರತಿಯೊಂದಕ್ಕೆ n × l ಕಂಡುಹಿಡಿದು n ಮತ್ತು 1/l ನಕ್ಷೆ ಎಳೆಯಿರಿ.')],
        precautions=SONO_PRE,
        conclusion=W('n × l is the same for every fork and the n–1/l graph is a straight line through the origin: frequency is inversely proportional to the resonating length.', 'हर स्वरित्र के लिए n × l समान है और n–1/l ग्राफ़ मूल बिंदु से जाने वाली सीधी रेखा है: आवृत्ति अनुनादी लंबाई के व्युत्क्रमानुपाती है।', 'ಪ್ರತಿ ಶ್ರುತಿಕವೆಗೆ n × l ಒಂದೇ; n–1/l ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ ಸರಳರೇಖೆ: ಆವರ್ತನ ಅನುನಾದ ಉದ್ದಕ್ಕೆ ವಿಲೋಮಾನುಪಾತೀಯ.'),
        viva=[Q(W('Why does the paper rider fly off?', 'कागज़ का सवार क्यों उड़ जाता है?', 'ಕಾಗದದ ಸವಾರ ಏಕೆ ಹಾರುತ್ತದೆ?'), W('At resonance the wire vibrates with large amplitude at the antinode in the middle.', 'अनुनाद पर तार बीच के प्रस्पंद पर बड़े आयाम से कंपन करता है।', 'ಅನುನಾದದಲ್ಲಿ ತಂತಿ ಮಧ್ಯದ ಪ್ರಸ್ಪಂದದಲ್ಲಿ ದೊಡ್ಡ ವಿಸ್ತಾರದಿಂದ ಕಂಪಿಸುತ್ತದೆ.')),
              Q(W('What kind of waves are set up in the wire?', 'तार में कैसी तरंगें बनती हैं?', 'ತಂತಿಯಲ್ಲಿ ಯಾವ ರೀತಿಯ ತರಂಗಗಳು ಉಂಟಾಗುತ್ತವೆ?'), W('Transverse stationary waves, with nodes at the bridges.', 'अनुप्रस्थ अप्रगामी तरंगें, सेतुओं पर निस्पंद सहित।', 'ಅಡ್ಡ ಸ್ಥಿರ ತರಂಗಗಳು, ಸೇತುವೆಗಳಲ್ಲಿ ನಿಸ್ಪಂದಗಳು.')),
              Q(W('Why is the sonometer box hollow?', 'स्वरमापी का बॉक्स खोखला क्यों होता है?', 'ಸೋನೋಮೀಟರ್ ಪೆಟ್ಟಿಗೆ ಟೊಳ್ಳು ಏಕೆ?'), W('Its air vibrates in forced vibration and makes the sound louder.', 'इसकी वायु प्रणोदित कंपन करती है और ध्वनि को तेज़ करती है।', 'ಅದರ ಗಾಳಿ ಬಲವಂತ ಕಂಪನದಿಂದ ಧ್ವನಿಯನ್ನು ಜೋರಾಗಿಸುತ್ತದೆ.')),
              Q(W('What is resonance?', 'अनुनाद क्या है?', 'ಅನುನಾದ ಎಂದರೇನು?'), W('Large vibration when a driving frequency equals the natural frequency.', 'जब चालक आवृत्ति स्वाभाविक आवृत्ति के बराबर हो तब बड़ा कंपन।', 'ಚಾಲಕ ಆವರ್ತನ ಸಹಜ ಆವರ್ತನಕ್ಕೆ ಸಮವಾದಾಗ ದೊಡ್ಡ ಕಂಪನ.')),
              Q(W('How does μ change for a thicker wire of the same metal?', 'उसी धातु के मोटे तार के लिए μ कैसे बदलता है?', 'ಅದೇ ಲೋಹದ ದಪ್ಪ ತಂತಿಗೆ μ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ?'), W('It increases as the square of the diameter, so the frequency falls.', 'यह व्यास के वर्ग के अनुपात में बढ़ता है, इसलिए आवृत्ति घटती है।', 'ವ್ಯಾಸದ ವರ್ಗದಂತೆ ಹೆಚ್ಚುತ್ತದೆ, ಆದ್ದರಿಂದ ಆವರ್ತನ ಕಡಿಮೆಯಾಗುತ್ತದೆ.'))])

    lab(id='sonometer-law-of-tension', bench='sonometer-laws', setup={'task': 'tension', 'fork': 320.0}, **puc1,
        keywords=['sonometer', 'law of tension', 'tension and length', 'waves', 'tuning fork', 'resonance', 'stretched string'],
        title=W('Sonometer: resonating length and tension', 'स्वरमापी: अनुनादी लंबाई और तनाव', 'ಸೋನೋಮೀಟರ್: ಅನುನಾದ ಉದ್ದ ಮತ್ತು ಎಳೆತ'),
        summary=W('With one tuning fork, find the resonating length at several tensions; l/√T stays constant.', 'एक स्वरित्र से कई तनावों पर अनुनादी लंबाई ढूँढें; l/√T नियत रहता है।', 'ಒಂದು ಶ್ರುತಿಕವೆಯಿಂದ ಹಲವು ಎಳೆತಗಳಲ್ಲಿ ಅನುನಾದ ಉದ್ದ ಕಂಡುಹಿಡಿಯಿರಿ; l/√T ಸ್ಥಿರ.'),
        aim=W('To study the relation between the resonating length and the tension of a stretched wire for a given frequency using a sonometer.', 'स्वरमापी से दी गई आवृत्ति के लिए तने तार की अनुनादी लंबाई और तनाव के बीच संबंध का अध्ययन करना।', 'ಸೋನೋಮೀಟರ್ ಬಳಸಿ ನೀಡಿದ ಆವರ್ತನಕ್ಕೆ ಬಿಗಿದ ತಂತಿಯ ಅನುನಾದ ಉದ್ದ ಮತ್ತು ಎಳೆತದ ಸಂಬಂಧ ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
        principle=W('From n = (1/2l)√(T/μ), at fixed n the resonating length l ∝ √T. The graph of l against √T is a straight line through the origin, and its slope gives μ = 1/(4n² × slope²).', 'n = (1/2l)√(T/μ) से, नियत n पर अनुनादी लंबाई l ∝ √T. l और √T का ग्राफ़ मूल बिंदु से जाने वाली सीधी रेखा है, और उसकी प्रवणता से μ = 1/(4n² × प्रवणता²) मिलता है।', 'n = (1/2l)√(T/μ) ನಿಂದ, ಸ್ಥಿರ n ನಲ್ಲಿ ಅನುನಾದ ಉದ್ದ l ∝ √T. l ಮತ್ತು √T ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ ಸರಳರೇಖೆ; ಅದರ ಇಳಿಜಾರು μ = 1/(4n² × ಇಳಿಜಾರು²) ನೀಡುತ್ತದೆ.'),
        apparatus=SONO_APP,
        steps=[W('Choose one fork (say 320 Hz) and hang 1 kg on the hanger.', 'एक स्वरित्र चुनें (मान लें 320 Hz) और हैंगर पर 1 kg लटकाएँ।', 'ಒಂದು ಶ್ರುತಿಕವೆ ಆರಿಸಿ (ಉದಾ. 320 Hz) ಹ್ಯಾಂಗರ್‌ಗೆ 1 kg ತೂಗುಹಾಕಿ.'),
               W('Find the resonating length with the paper rider.', 'कागज़ के सवार से अनुनादी लंबाई ढूँढें।', 'ಕಾಗದದ ಸವಾರದಿಂದ ಅನುನಾದ ಉದ್ದ ಕಂಡುಹಿಡಿಯಿರಿ.'),
               W('Increase the load in steps and find the new length each time.', 'भार चरणों में बढ़ाएँ और हर बार नई लंबाई ढूँढें।', 'ಭಾರವನ್ನು ಹಂತಗಳಲ್ಲಿ ಹೆಚ್ಚಿಸಿ ಪ್ರತಿ ಬಾರಿ ಹೊಸ ಉದ್ದ ಕಂಡುಹಿಡಿಯಿರಿ.'),
               W('Work out T = Mg, √T and l/√T for each.', 'प्रत्येक के लिए T = Mg, √T और l/√T निकालें।', 'ಪ್ರತಿಯೊಂದಕ್ಕೆ T = Mg, √T ಮತ್ತು l/√T ಲೆಕ್ಕಿಸಿ.'),
               W('Plot l against √T and find μ from the slope.', 'l और √T का ग्राफ़ बनाएँ और प्रवणता से μ ज्ञात करें।', 'l ಮತ್ತು √T ನಕ್ಷೆ ಎಳೆದು ಇಳಿಜಾರಿನಿಂದ μ ಕಂಡುಹಿಡಿಯಿರಿ.')],
        precautions=SONO_PRE,
        conclusion=W('l/√T is the same at every tension and the l–√T graph is a straight line through the origin: the resonating length is proportional to the square root of the tension.', 'हर तनाव पर l/√T समान है और l–√T ग्राफ़ मूल बिंदु से जाने वाली सीधी रेखा है: अनुनादी लंबाई तनाव के वर्गमूल के अनुक्रमानुपाती है।', 'ಪ್ರತಿ ಎಳೆತದಲ್ಲಿ l/√T ಒಂದೇ; l–√T ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ ಸರಳರೇಖೆ: ಅನುನಾದ ಉದ್ದ ಎಳೆತದ ವರ್ಗಮೂಲಕ್ಕೆ ಅನುಪಾತೀಯ.'),
        viva=[Q(W('How is the tension in the wire found?', 'तार में तनाव कैसे ज्ञात होता है?', 'ತಂತಿಯ ಎಳೆತ ಹೇಗೆ ತಿಳಿಯುತ್ತದೆ?'), W('T = Mg, the weight of the hanger and its masses.', 'T = Mg, हैंगर और बाटों का भार।', 'T = Mg, ಹ್ಯಾಂಗರ್ ಮತ್ತು ತೂಕಗಳ ಭಾರ.')),
              Q(W('If the tension is made four times, what happens to the frequency of a fixed length?', 'तनाव चार गुना करने पर नियत लंबाई की आवृत्ति का क्या होता है?', 'ಎಳೆತ ನಾಲ್ಕು ಪಟ್ಟು ಮಾಡಿದರೆ ಸ್ಥಿರ ಉದ್ದದ ಆವರ್ತನಕ್ಕೆ ಏನಾಗುತ್ತದೆ?'), W('It doubles, because n ∝ √T.', 'यह दोगुनी हो जाती है, क्योंकि n ∝ √T.', 'ಅದು ಎರಡು ಪಟ್ಟಾಗುತ್ತದೆ, ಏಕೆಂದರೆ n ∝ √T.')),
              Q(W('What is the speed of the wave on the wire?', 'तार पर तरंग की चाल क्या है?', 'ತಂತಿಯ ಮೇಲಿನ ತರಂಗದ ವೇಗ ಎಷ್ಟು?'), W('v = √(T/μ) = 2nl.', 'v = √(T/μ) = 2nl.', 'v = √(T/μ) = 2nl.')),
              Q(W('Why use a hanger and not a spring balance?', 'स्प्रिंग तुला के बजाय हैंगर क्यों?', 'ಸ್ಪ್ರಿಂಗ್ ತಕ್ಕಡಿಯ ಬದಲು ಹ್ಯಾಂಗರ್ ಏಕೆ?'), W('A hanging weight keeps the tension steady while the wire vibrates.', 'लटकता भार तार के कंपन के दौरान तनाव स्थिर रखता है।', 'ತೂಗುವ ಭಾರ ತಂತಿ ಕಂಪಿಸುವಾಗ ಎಳೆತ ಸ್ಥಿರವಾಗಿಡುತ್ತದೆ.')),
              Q(W('Name the law verified.', 'सत्यापित नियम का नाम बताइए।', 'ಪರಿಶೀಲಿಸಿದ ನಿಯಮ ಹೆಸರಿಸಿ.'), W('The law of tension for transverse vibrations of a stretched string.', 'तनी डोरी के अनुप्रस्थ कंपनों का तनाव का नियम।', 'ಬಿಗಿದ ದಾರದ ಅಡ್ಡ ಕಂಪನಗಳ ಎಳೆತದ ನಿಯಮ.'))])

    # --------------------------------------------- refractive index of a liquid
    lab(id='liquid-refractive-index', bench='liquid-lens', **puc2,
        keywords=['refractive index of a liquid', 'convex lens', 'plane mirror', 'ray optics', 'ray optics and optical instruments', 'parallax', 'liquid lens'],
        title=W('Refractive index of a liquid with a convex lens and a plane mirror', 'उत्तल लेंस और समतल दर्पण से द्रव का अपवर्तनांक', 'ಪೀನ ಮಸೂರ ಮತ್ತು ಸಮತಲ ದರ್ಪಣದಿಂದ ದ್ರವದ ವಕ್ರೀಭವನಾಂಕ'),
        summary=W('Find the focal length of a lens on a mirror by removing parallax, then again with a liquid under it; the liquid lens gives n.', 'लंबन हटाकर दर्पण पर लेंस की फोकस दूरी ज्ञात करें, फिर उसके नीचे द्रव रखकर दोबारा; द्रव लेंस से n मिलता है।', 'ದೃಷ್ಟಿಭ್ರಮೆ ತೆಗೆದು ದರ್ಪಣದ ಮೇಲಿನ ಮಸೂರದ ನಾಭಿದೂರ ಕಂಡುಹಿಡಿಯಿರಿ, ನಂತರ ಕೆಳಗೆ ದ್ರವ ಇಟ್ಟು ಮತ್ತೆ; ದ್ರವ ಮಸೂರ n ನೀಡುತ್ತದೆ.'),
        aim=W('To determine the refractive index of a liquid using a convex lens and a plane mirror.', 'उत्तल लेंस और समतल दर्पण से किसी द्रव का अपवर्तनांक ज्ञात करना।', 'ಪೀನ ಮಸೂರ ಮತ್ತು ಸಮತಲ ದರ್ಪಣ ಬಳಸಿ ದ್ರವದ ವಕ್ರೀಭವನಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('A pin at the focus of a lens resting on a mirror coincides with its own image (no parallax). With liquid under the lens, a plano-concave liquid lens of focal length f₂ joins it: 1/F = 1/f₁ + 1/f₂, so f₂ = f₁F/(f₁ − F), and n = 1 + R/|f₂|, R being the lens surface’s radius of curvature.', 'दर्पण पर रखे लेंस की फोकस पर पिन अपने ही प्रतिबिंब से मिल जाती है (लंबन नहीं)। लेंस के नीचे द्रव होने पर f₂ फोकस दूरी का समतल-अवतल द्रव लेंस जुड़ता है: 1/F = 1/f₁ + 1/f₂, अतः f₂ = f₁F/(f₁ − F), और n = 1 + R/|f₂|, जहाँ R लेंस सतह की वक्रता त्रिज्या है।', 'ದರ್ಪಣದ ಮೇಲಿನ ಮಸೂರದ ನಾಭಿಯಲ್ಲಿನ ಸೂಜಿ ತನ್ನದೇ ಪ್ರತಿಬಿಂಬದೊಂದಿಗೆ ಹೊಂದುತ್ತದೆ (ದೃಷ್ಟಿಭ್ರಮೆ ಇಲ್ಲ). ಮಸೂರದ ಕೆಳಗೆ ದ್ರವ ಇದ್ದಾಗ f₂ ನಾಭಿದೂರದ ಸಮತಲ-ನಿಮ್ನ ದ್ರವ ಮಸೂರ ಸೇರುತ್ತದೆ: 1/F = 1/f₁ + 1/f₂, ಆದ್ದರಿಂದ f₂ = f₁F/(f₁ − F), n = 1 + R/|f₂|; R ಮಸೂರದ ಮೇಲ್ಮೈಯ ವಕ್ರತಾ ತ್ರಿಜ್ಯ.'),
        apparatus=[W('Convex lens and plane mirror', 'उत्तल लेंस और समतल दर्पण', 'ಪೀನ ಮಸೂರ ಮತ್ತು ಸಮತಲ ದರ್ಪಣ'), W('Optical needle on a stand with clamp', 'क्लैंप सहित स्टैंड पर प्रकाशीय सुई', 'ಕ್ಲ್ಯಾಂಪ್ ಸಹಿತ ಸ್ಟ್ಯಾಂಡ್ ಮೇಲಿನ ಪ್ರಕಾಶ ಸೂಜಿ'), W('Liquids: water, glycerine, kerosene', 'द्रव: पानी, ग्लिसरीन, केरोसिन', 'ದ್ರವಗಳು: ನೀರು, ಗ್ಲಿಸರಿನ್, ಸೀಮೆಎಣ್ಣೆ'), W('Spherometer and metre scale', 'गोलाईमापी और मीटर पैमाना', 'ಗೋಳಮಾಪಕ ಮತ್ತು ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿ')],
        steps=[W('Place the lens on the mirror and the pin above it; move the pin until the tip and its inverted image show no parallax.', 'लेंस को दर्पण पर और पिन को उसके ऊपर रखें; पिन खिसकाएँ जब तक नोक और उसके उलटे प्रतिबिंब में लंबन न रहे।', 'ಮಸೂರವನ್ನು ದರ್ಪಣದ ಮೇಲೆ, ಸೂಜಿಯನ್ನು ಅದರ ಮೇಲೆ ಇಡಿ; ತುದಿ ಮತ್ತು ಅದರ ತಲೆಕೆಳಗಾದ ಪ್ರತಿಬಿಂಬದಲ್ಲಿ ದೃಷ್ಟಿಭ್ರಮೆ ಇಲ್ಲದವರೆಗೆ ಸೂಜಿ ಸರಿಸಿ.'),
               W('Measure x₁ (to the mirror) and x₂ (to the top of the lens); f₁ = (x₁ + x₂)/2.', 'x₁ (दर्पण तक) और x₂ (लेंस के ऊपर तक) मापें; f₁ = (x₁ + x₂)/2.', 'x₁ (ದರ್ಪಣದವರೆಗೆ) ಮತ್ತು x₂ (ಮಸೂರದ ಮೇಲ್ಭಾಗದವರೆಗೆ) ಅಳೆಯಿರಿ; f₁ = (x₁ + x₂)/2.'),
               W('Put a few drops of liquid on the mirror, replace the lens and find F the same way.', 'दर्पण पर द्रव की कुछ बूँदें डालें, लेंस वापस रखें और इसी तरह F ज्ञात करें।', 'ದರ್ಪಣದ ಮೇಲೆ ಕೆಲವು ಹನಿ ದ್ರವ ಹಾಕಿ, ಮಸೂರವನ್ನು ಮತ್ತೆ ಇಟ್ಟು F ಹಾಗೆಯೇ ಕಂಡುಹಿಡಿಯಿರಿ.'),
               W('Find R of the lens surface with a spherometer.', 'गोलाईमापी से लेंस सतह का R ज्ञात करें।', 'ಗೋಳಮಾಪಕದಿಂದ ಮಸೂರದ ಮೇಲ್ಮೈಯ R ಕಂಡುಹಿಡಿಯಿರಿ.'),
               W('Work out f₂ = f₁F/(f₁ − F) and n = 1 + R/|f₂| for each liquid.', 'प्रत्येक द्रव के लिए f₂ = f₁F/(f₁ − F) और n = 1 + R/|f₂| निकालें।', 'ಪ್ರತಿ ದ್ರವಕ್ಕೆ f₂ = f₁F/(f₁ − F) ಮತ್ತು n = 1 + R/|f₂| ಲೆಕ್ಕಿಸಿ.')],
        precautions=[W('Use only a thin layer of liquid with no air bubbles.', 'केवल पतली द्रव परत लें जिसमें हवा के बुलबुले न हों।', 'ಗಾಳಿ ಗುಳ್ಳೆಗಳಿಲ್ಲದ ತೆಳು ದ್ರವ ಪದರ ಮಾತ್ರ ಬಳಸಿ.'), W('Look from directly above and move the eye sideways to test parallax.', 'ठीक ऊपर से देखें और लंबन जाँचने के लिए आँख बगल में हिलाएँ।', 'ನೇರ ಮೇಲಿನಿಂದ ನೋಡಿ, ದೃಷ್ಟಿಭ್ರಮೆ ಪರೀಕ್ಷಿಸಲು ಕಣ್ಣನ್ನು ಪಕ್ಕಕ್ಕೆ ಸರಿಸಿ.'), W('Clean the mirror and lens between liquids.', 'द्रव बदलते समय दर्पण और लेंस साफ़ करें।', 'ದ್ರವಗಳ ನಡುವೆ ದರ್ಪಣ ಮತ್ತು ಮಸೂರ ಸ್ವಚ್ಛಗೊಳಿಸಿ.')],
        conclusion=W('The liquid lengthens the focal length; the liquid lens’s f₂ gives refractive indices close to 1.33 for water, 1.44 for kerosene and 1.47 for glycerine.', 'द्रव फोकस दूरी बढ़ाता है; द्रव लेंस के f₂ से पानी के लिए 1.33, केरोसिन के लिए 1.44 और ग्लिसरीन के लिए 1.47 के निकट अपवर्तनांक मिलते हैं।', 'ದ್ರವ ನಾಭಿದೂರ ಹೆಚ್ಚಿಸುತ್ತದೆ; ದ್ರವ ಮಸೂರದ f₂ ನೀರಿಗೆ 1.33, ಸೀಮೆಎಣ್ಣೆಗೆ 1.44 ಮತ್ತು ಗ್ಲಿಸರಿನ್‌ಗೆ 1.47 ಹತ್ತಿರದ ವಕ್ರೀಭವನಾಂಕ ನೀಡುತ್ತದೆ.'),
        viva=[Q(W('What kind of lens does the liquid form?', 'द्रव कैसा लेंस बनाता है?', 'ದ್ರವ ಯಾವ ರೀತಿಯ ಮಸೂರ ರೂಪಿಸುತ್ತದೆ?'), W('A plano-concave lens (flat on the mirror side).', 'एक समतल-अवतल लेंस (दर्पण की ओर समतल)।', 'ಸಮತಲ-ನಿಮ್ನ ಮಸೂರ (ದರ್ಪಣದ ಕಡೆ ಸಮತಟ್ಟು).')),
              Q(W('What is parallax?', 'लंबन क्या है?', 'ದೃಷ್ಟಿಭ್ರಮೆ ಎಂದರೇನು?'), W('The apparent shift of one object against another when the eye moves.', 'आँख हिलाने पर एक वस्तु का दूसरी के सापेक्ष आभासी विस्थापन।', 'ಕಣ್ಣು ಸರಿದಾಗ ಒಂದು ವಸ್ತು ಇನ್ನೊಂದಕ್ಕೆ ಹೋಲಿಸಿ ತೋರುವ ಸ್ಥಳಾಂತರ.')),
              Q(W('Why does the image coincide with the pin at the focus?', 'फोकस पर प्रतिबिंब पिन से क्यों मिल जाता है?', 'ನಾಭಿಯಲ್ಲಿ ಪ್ರತಿಬಿಂಬ ಸೂಜಿಯೊಂದಿಗೆ ಏಕೆ ಹೊಂದುತ್ತದೆ?'), W('Rays from the focus leave the lens parallel, reflect straight back and return to the focus.', 'फोकस से किरणें लेंस से समांतर निकलती हैं, सीधे परावर्तित होकर फोकस पर लौटती हैं।', 'ನಾಭಿಯಿಂದ ಕಿರಣಗಳು ಸಮಾಂತರವಾಗಿ ಹೊರಟು ನೇರವಾಗಿ ಪ್ರತಿಫಲಿಸಿ ನಾಭಿಗೆ ಮರಳುತ್ತವೆ.')),
              Q(W('Why is F longer than f₁?', 'F, f₁ से लंबी क्यों है?', 'F, f₁ ಗಿಂತ ಉದ್ದ ಏಕೆ?'), W('The concave liquid lens diverges light and weakens the combination.', 'अवतल द्रव लेंस प्रकाश को फैलाता है और संयोजन की क्षमता घटाता है।', 'ನಿಮ್ನ ದ್ರವ ಮಸೂರ ಬೆಳಕನ್ನು ಚದುರಿಸಿ ಸಂಯೋಜನೆಯನ್ನು ದುರ್ಬಲಗೊಳಿಸುತ್ತದೆ.')),
              Q(W('Which formula gives n from f₂?', 'f₂ से n किस सूत्र से मिलता है?', 'f₂ ನಿಂದ n ಯಾವ ಸೂತ್ರದಿಂದ ಬರುತ್ತದೆ?'), W("The lens maker's formula: 1/f₂ = (n − 1)(−1/R).", 'लेंस निर्माता सूत्र: 1/f₂ = (n − 1)(−1/R).', 'ಮಸೂರ ತಯಾರಕರ ಸೂತ್ರ: 1/f₂ = (n − 1)(−1/R).'))])
